/*
 * FlowCode section library: the styles every library section shares. Only design tokens (src/styles/tokens.css):
 * no raw colors, sizes or fonts, so each section takes on the app's look. Classes start with "fl-".
 * License: MIT (FlowCode). Section patterns informed by MIT/CC BY libraries listed in THIRD_PARTY_NOTICES.md.
 */

/* ── Section frame ── */
.fl-section { padding-block: var(--space-9); padding-inline: var(--space-5); }
/* Type on phones: every library font size is 2px smaller (never under 11px). */
:root { --fs-shrink: 0px; }
@media (max-width: 640px) { :root { --fs-shrink: 2px; } }
/* Canvas: a gray page with white cards, panels and fields on it (app screens and components). */
.fl-section--canvas { background: var(--color-surface-sunken); --color-surface: var(--color-bg); --surface-bg: var(--color-bg); }
/* A page that is only one canvas section (a piece's preview) is gray to the edges. */
html:has(body > #root > .fl-section--canvas:only-child), html:has(body > #root > .fl-section--canvas:only-child) body { background: var(--color-surface-sunken); }
.fl-section--tint { background: var(--color-secondary-surface, var(--color-surface-sunken)); }
/* A specimen of the building blocks themselves (the catalog's own pieces): even padding, no page rhythm. */
/* A piece is shown in a column far narrower than the window - a library card, a modal, a page beside a sidebar - so
   its own rules below ask its width, not the window's. That is what container-type gives them. */
.fl-section--specimen { padding: var(--space-5); container-type: inline-size; container-name: specimen; }
.fl-section--accent { background: var(--color-accent); color: var(--color-on-accent); }
.fl-wrap { width: 100%; max-width: var(--content-max, 72rem); margin-inline: auto; }
.fl-wrap--narrow { max-width: 48rem; }
.fl-head { display: grid; gap: var(--space-3); max-width: var(--measure); margin-bottom: var(--space-7); }
.fl-head--center { margin-inline: auto; text-align: center; justify-items: center; }
.fl-eyebrow { font: var(--weight-semibold) max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))) / 1 var(--font-sans); letter-spacing: var(--tracking-wide); text-transform: uppercase; color: var(--color-secondary, var(--color-accent)); }
.fl-section--accent .fl-eyebrow { color: var(--color-on-accent); opacity: 0.85; }
.fl-title { margin: 0; font-family: var(--font-display); font-size: var(--type-h1-size, max(11px, calc(var(--text-2xl) - var(--fs-shrink, 0px)))); font-weight: var(--type-h1-weight, var(--heading-weight, var(--weight-bold))); line-height: var(--type-h1-leading, var(--leading-tight)); letter-spacing: var(--tracking-tight); text-wrap: balance; }
.fl-title--xl { font-size: var(--type-display-size, max(11px, calc(var(--text-3xl) - var(--fs-shrink, 0px)))); line-height: var(--type-display-leading, var(--leading-tight)); }
.fl-title--md { font-size: var(--type-h2-size, max(11px, calc(var(--text-xl) - var(--fs-shrink, 0px)))); line-height: var(--type-h2-leading, var(--leading-snug)); }
.fl-lede { margin: 0; font-size: max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))); line-height: var(--leading-relaxed); color: var(--color-text-muted); max-width: var(--measure); }
.fl-section--accent .fl-lede { color: var(--color-on-accent); opacity: 0.88; }
.fl-text { margin: 0; line-height: var(--leading-relaxed); color: var(--color-text-muted); }
.fl-section--accent .fl-text { color: var(--color-on-accent); opacity: 0.85; }

/* ── Buttons and links ── */
.fl-actions { display: flex; flex-wrap: wrap; gap: var(--space-3); align-items: center; }
.fl-head--center .fl-actions { justify-content: center; }
.fl-btn {
  display: inline-flex; align-items: center; justify-content: center; gap: var(--space-2);
  min-height: var(--control-lg); padding-inline: var(--control-pad-lg); border-radius: var(--control-radius, var(--radius-md));
  font: var(--weight-semibold) var(--control-text-lg, max(11px, calc(var(--text-md) - var(--fs-shrink, 0px)))) / 1 var(--font-sans); text-decoration: none; cursor: pointer;
  border: var(--button-border, var(--control-border, 1px solid transparent)); box-shadow: var(--control-shadow, none);
  transition: background-color var(--duration-fast) var(--easing), transform var(--duration-fast) var(--easing), translate var(--duration-fast) var(--easing), box-shadow var(--duration-fast) var(--easing);
}
/* An icon in a button keeps its size, and the label stays on one line (an unsized svg grew and squeezed "Start free trial" onto three). */
.fl-btn { white-space: nowrap; }
@media (max-width: 420px) { .fl-btn { white-space: normal; } }
.fl-btn svg { width: 1.15em; height: 1.15em; flex: none; }
.fl-btn:hover { transform: translateY(var(--hover-lift, -1px)); translate: var(--hover-shift, none); box-shadow: var(--control-shadow-hover, none); }
.fl-btn:active { transform: scale(var(--press-scale, 0.98)); translate: var(--press-shift, none); box-shadow: var(--control-shadow-active, var(--control-shadow-hover, none)); }
.fl-btn:focus-visible, .fl-link:focus-visible, .fl-nav a:focus-visible, .fl-faq summary:focus-visible, .fl-input:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-btn:focus-visible, .fl-input:focus-visible { box-shadow: var(--control-shadow-focus, var(--focus-ring)); }
.fl-btn--primary { background: var(--accent-bg, var(--color-accent)); color: var(--color-on-accent); border-color: var(--control-edge, var(--color-accent)); }
.fl-btn--primary:hover { background: var(--color-accent-hover); }
.fl-btn--secondary { background: var(--control-bg, var(--color-surface)); color: var(--color-text); border-color: var(--control-edge, var(--color-border)); }
.fl-btn--on-accent { background: var(--color-on-accent); color: var(--color-accent); border-color: var(--color-on-accent); }
.fl-btn--ghost-on-accent { background: transparent; color: var(--color-on-accent); border-color: currentColor; }
.fl-link { color: var(--color-accent); font-weight: var(--weight-semibold); text-decoration: none; border-radius: var(--radius-sm); }
.fl-link:hover { text-decoration: underline; text-underline-offset: 3px; }

/* ── Surfaces ── */
.fl-card {
  /* Its corner and padding, exposed so what sits inside can nest its corners (see "Nested corners" below). */
  --_r: min(var(--surface-radius, var(--radius-lg)), 24px); --_p: var(--space-6); --_in: clamp(calc(var(--_r) * 0.5), calc(var(--_r) - var(--_p)), calc(var(--_r) * 0.75));
  display: grid; gap: var(--space-3); align-content: start; padding: var(--_p);
  background: var(--surface-bg, var(--color-surface)); border: var(--surface-border, 1px solid var(--color-border));
  border-radius: var(--_r); box-shadow: var(--surface-shadow, none); backdrop-filter: var(--surface-blur, none); -webkit-backdrop-filter: var(--surface-blur, none);
}
.fl-card h3, .fl-card h4 { margin: 0; font-family: var(--font-display); font-size: var(--type-h3-size, max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px)))); font-weight: var(--type-h3-weight, var(--weight-semibold)); line-height: var(--leading-snug); }
.fl-media {
  position: relative; display: grid; place-items: center; aspect-ratio: 4 / 3; max-width: 100%; overflow: hidden;
  border-radius: min(var(--surface-radius, var(--radius-lg)), 24px); color: var(--color-text-muted); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); text-align: center; padding: var(--space-5);
  background:
    radial-gradient(120% 90% at 0% 0%, color-mix(in srgb, var(--color-secondary, var(--color-accent)) 22%, transparent), transparent 60%),
    linear-gradient(135deg, var(--color-surface-sunken), var(--color-surface));
  border: var(--surface-border, 1px solid var(--color-border));
}
.fl-media--wide { aspect-ratio: 16 / 9; }
.fl-media--square { aspect-ratio: 1; }
.fl-media--round { aspect-ratio: 1; border-radius: 50%; padding: var(--space-2); }
.fl-icon {
  display: inline-grid; place-items: center; width: 2.75rem; height: 2.75rem; border-radius: var(--radius-md);
  background: var(--color-secondary-surface, color-mix(in srgb, var(--color-accent) 12%, var(--color-surface))); color: var(--color-secondary, var(--color-accent));
}
.fl-icon svg { width: 1.25rem; height: 1.25rem; }

/* ── Nested corners ── A padded rounded container (card, dialog, panel, tile) sets --_r (its corner, never past 24px),
   --_p (its padding) and --_in, the corner for what sits inside it: outer minus padding, kept between half and three
   quarters of the outer so the two curves stay concentric. Low specificity, so a piece that sets its own corner wins. */
:where(.fl-card, .fl-dlg-panel, .fl-dlg-sheet) :where(.fl-media:not(.fl-media--round), pre, .fl-well),
:where(.fl-card, .fl-dlg-panel) > :where(img, picture, video) { border-radius: var(--_in); }
/* A field inside a card or dialog: its own field corner, or the nested one when that is smaller. */
:where(.fl-card, .fl-dlg-panel, .fl-dlg-sheet) .fl-input { border-radius: min(var(--field-radius, min(var(--control-radius, var(--radius-sm)), 24px)), var(--_in)); }

/* ── Grids ── */
.fl-grid { display: grid; gap: var(--space-5); }
.fl-grid--2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.fl-grid--3 { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.fl-grid--4 { grid-template-columns: repeat(4, minmax(0, 1fr)); }
.fl-split { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--space-8); align-items: center; }
.fl-split--start { align-items: start; }

/* ── Navigation ── */
.fl-nav { position: sticky; top: 0; z-index: 10; background: var(--header-bg, var(--color-surface)); border-bottom: 1px solid var(--color-border); }
.fl-nav__row { display: flex; align-items: center; gap: var(--space-6); min-height: 4rem; padding-inline: var(--space-5); max-width: var(--content-max, 72rem); margin-inline: auto; }
.fl-nav__brand { font: var(--weight-bold) max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))) / 1 var(--font-display); color: var(--color-text); text-decoration: none; }
.fl-nav__links { display: flex; gap: var(--space-5); margin: 0; padding: 0; list-style: none; }
.fl-nav__links a { color: var(--color-text-muted); text-decoration: none; font-weight: var(--weight-medium); border-radius: var(--radius-sm); }
.fl-nav__links a:hover, .fl-nav__links a[aria-current="page"] { color: var(--color-text); }
.fl-nav__end { margin-left: auto; display: flex; gap: var(--space-3); align-items: center; }
.fl-nav--center .fl-nav__row { justify-content: space-between; }
.fl-nav__menu { display: none; }

/* ── Lists, quotes, stats ── */
.fl-checks { display: grid; gap: var(--space-3); margin: 0; padding: 0; list-style: none; }
.fl-checks li { display: grid; grid-template-columns: auto 1fr; gap: var(--space-3); align-items: start; line-height: var(--leading-normal); }
.fl-tick { display: inline-grid; place-items: center; width: 1.25rem; height: 1.25rem; border-radius: 50%; background: color-mix(in srgb, var(--color-success) 16%, transparent); color: var(--color-success); }
.fl-tick svg { width: 0.8rem; height: 0.8rem; }
.fl-quote { margin: 0; font-size: max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))); line-height: var(--leading-relaxed); color: var(--color-text); }
.fl-quote--xl { font-family: var(--font-display); font-size: max(11px, calc(var(--text-xl) - var(--fs-shrink, 0px))); line-height: var(--leading-snug); text-wrap: balance; }
.fl-person { display: flex; gap: var(--space-3); align-items: center; }
.fl-person__avatar { width: 2.75rem; height: 2.75rem; border-radius: 50%; display: grid; place-items: center; font-weight: var(--weight-bold); background: var(--color-secondary-surface, color-mix(in srgb, var(--color-accent) 18%, var(--color-surface))); color: var(--color-text); flex: none; }
.fl-person strong { display: block; }
.fl-person span { color: var(--color-text-muted); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-stat { display: grid; gap: var(--space-1); }
.fl-stat strong { font: var(--weight-bold) max(11px, calc(var(--text-2xl) - var(--fs-shrink, 0px))) / 1.1 var(--font-display); font-variant-numeric: tabular-nums; }
.fl-stat span { color: var(--color-text-muted); }
.fl-section--accent .fl-stat span { color: var(--color-on-accent); opacity: 0.85; }
.fl-meta { font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }

/* ── Pricing ── */
.fl-price { display: flex; align-items: baseline; gap: var(--space-2); }
.fl-price strong { font: var(--weight-bold) max(11px, calc(var(--text-2xl) - var(--fs-shrink, 0px))) / 1 var(--font-display); font-variant-numeric: tabular-nums; }
.fl-card--featured { border-color: var(--surface-edge, var(--color-accent)); box-shadow: var(--surface-shadow-hover, var(--surface-shadow, none)); position: relative; }
.fl-badge { justify-self: start; padding: var(--space-1) var(--space-3); border-radius: 999px; font: var(--weight-semibold) max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))) / 1.4 var(--font-sans); background: var(--color-secondary-surface, color-mix(in srgb, var(--color-accent) 14%, transparent)); color: var(--color-text); }
.fl-toggle { display: inline-flex; padding: var(--space-1); gap: var(--space-1); border-radius: var(--pill-radius, 999px); background: var(--color-surface-sunken); border: 1px solid var(--color-border); box-shadow: var(--well-shadow, none); }
.fl-toggle button { min-height: var(--control-sm); padding-inline: var(--space-5); border: 0; border-radius: var(--pill-radius, 999px); background: transparent; color: var(--color-text-muted); font: var(--weight-semibold) max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))) / 1 var(--font-sans); cursor: pointer; }
.fl-toggle button[aria-pressed="true"] { background: var(--color-surface); color: var(--color-text); box-shadow: var(--surface-shadow, none); }
.fl-toggle button:focus-visible { outline: none; box-shadow: var(--focus-ring); }
/* Labels stay on one line; on a phone the options tighten up. */
.fl-toggle button { white-space: nowrap; }
@media (max-width: 640px) { .fl-toggle button { padding-inline: var(--space-3); } }

/* ── FAQ ── */
.fl-faq { display: grid; border-top: 1px solid var(--color-border); }
.fl-faq details { border-bottom: 1px solid var(--color-border); }
.fl-faq summary { display: flex; justify-content: space-between; gap: var(--space-4); padding-block: var(--space-5); font-weight: var(--weight-semibold); cursor: pointer; list-style: none; border-radius: var(--radius-sm); }
.fl-faq summary::-webkit-details-marker { display: none; }
.fl-faq summary::after { content: "+"; color: var(--color-secondary, var(--color-accent)); font-size: max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))); line-height: 1; transition: transform var(--duration-fast) var(--easing); }
.fl-faq details[open] summary::after { transform: rotate(45deg); }
.fl-faq details p { margin: 0 0 var(--space-5); color: var(--color-text-muted); line-height: var(--leading-relaxed); max-width: var(--measure); }

/* ── Forms ── */
.fl-form { display: grid; gap: var(--space-4); }
/* Fields keep their natural height: in a row, a field without a hint never stretches its input to match a neighbour. */
.fl-field { display: grid; gap: var(--space-2); align-content: start; }
.fl-field label { font-weight: var(--weight-semibold); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-input {
  width: 100%; min-height: var(--control-md); padding: var(--space-3) var(--control-pad-md); border-radius: var(--field-radius, min(var(--control-radius, var(--radius-sm)), 24px));
  border: var(--control-border, 1px solid var(--color-border-strong)); background: var(--control-bg, var(--color-surface)); color: var(--color-text); font: inherit; box-shadow: var(--well-shadow, none);
}
textarea.fl-input { min-height: 8rem; resize: vertical; }
/* One height for every single-line field, so a date picker or select sits level with the text box beside it. */
input.fl-input:where(:not([type="checkbox"], [type="radio"], [type="range"])), select.fl-input { height: var(--control-md); padding-block: 0; }
.fl-inline-form { display: flex; gap: var(--space-3); flex-wrap: wrap; align-items: stretch; }
.fl-inline-form .fl-input { flex: 1 1 16rem; width: auto; }
/* The field and the button beside it are one control to the eye, so they share a height: the button's, because
   shrinking the button to the field's would weaken the thing being asked for. Height, not min-height, because the
   rule above sets height outright. */
.fl-inline-form input.fl-input:where(:not([type="checkbox"], [type="radio"], [type="range"])),
.fl-inline-form select.fl-input { height: var(--control-lg); }
.fl-note { font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }
.fl-done { padding: var(--space-4); border-radius: var(--radius-md); background: color-mix(in srgb, var(--color-success) 12%, transparent); color: var(--color-success); font-weight: var(--weight-semibold); }

/* ── Footer ── */
.fl-footer { padding: var(--space-8) var(--space-5) var(--space-6); border-top: 1px solid var(--color-border); background: var(--color-surface); }
.fl-footer__cols { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: var(--space-7); }
.fl-footer h4 { margin: 0 0 var(--space-3); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); text-transform: uppercase; letter-spacing: var(--tracking-wide); color: var(--color-text-muted); }
.fl-footer ul { margin: 0; padding: 0; list-style: none; display: grid; gap: var(--space-2); }
.fl-footer a { color: var(--color-text); text-decoration: none; }
.fl-footer a:hover { color: var(--color-accent); }
.fl-footer__base { display: flex; flex-wrap: wrap; justify-content: space-between; gap: var(--space-3); margin-top: var(--space-7); padding-top: var(--space-5); border-top: 1px solid var(--color-border); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }

/* ── Hero, call-to-action, newsletter and simple footer entrances (fl-hx) ──
   One entrance per section, once: the words rise in order (stagger capped by --stagger-max), then the picture, form or
   numbers. The piece's script adds is-waiting / is-entering; without it, with reduced motion or animation off, nothing
   is ever hidden. */
.fl-hx-seq > * { --fl-hx-i: 5; }
.fl-hx-seq > :nth-child(1) { --fl-hx-i: 0; }
.fl-hx-seq > :nth-child(2) { --fl-hx-i: 1; }
.fl-hx-seq > :nth-child(3) { --fl-hx-i: 2; }
.fl-hx-seq > :nth-child(4) { --fl-hx-i: 3; }
.fl-hx-seq > :nth-child(5) { --fl-hx-i: 4; }
.fl-hx-seq--after { --fl-hx-base: 2; }
.fl-hx .fl-split > :not(.fl-hx-seq) { --fl-hx-i: 2; }
.fl-hx.is-waiting :is(.fl-hx-seq > *, .fl-split > :not(.fl-hx-seq)) { opacity: 0; }
.fl-hx.is-entering :is(.fl-hx-seq > *, .fl-split > :not(.fl-hx-seq)) {
  animation: fl-hx-rise var(--duration-slow, 320ms) var(--ease-out, ease-out) backwards;
  animation-delay: min(calc((var(--fl-hx-i, 0) + var(--fl-hx-base, 0)) * var(--stagger, 40ms)), var(--stagger-max, 200ms));
}
/* The picture or form beside the words settles from slightly smaller instead of rising. */
.fl-hx.is-entering .fl-split > :not(.fl-hx-seq) { animation-name: fl-hx-settle; }
@keyframes fl-hx-rise { from { opacity: 0; translate: 0 var(--enter-distance, 8px); } }
@keyframes fl-hx-settle { from { opacity: 0; scale: 0.98; } }
/* Proof numbers lift a little under the pointer. */
.fl-hx .fl-card.fl-stat { transition: translate var(--duration-fast, 120ms) var(--ease-out, ease-out), box-shadow var(--duration-fast, 120ms) var(--ease-out, ease-out); }
.fl-hx .fl-card.fl-stat:hover { translate: 0 calc(var(--hover-lift, -1px) * 2); box-shadow: var(--surface-shadow-hover, var(--surface-shadow, none)); }
/* The newsletter's thank-you settles in where the form was. */
.fl-hx .fl-split > .fl-hx-done { animation: fl-hx-pop var(--duration-base, 200ms) var(--ease-spring, ease-out) backwards; }
@keyframes fl-hx-pop { from { scale: 0.96; } }
/* Simple footer: links get a straight underline that draws from the left; the brand warms to the accent. */
.fl-hx-foot :is(nav a, .fl-footer__base a, .fl-nav__brand) { position: relative; transition: color var(--duration-fast, 120ms) var(--ease-out, ease-out); }
.fl-hx-foot :is(nav a, .fl-footer__base a)::after { content: ""; position: absolute; left: 0; right: 0; bottom: -2px; height: 1px; background: currentColor; scale: 0 1; transform-origin: left center; transition: scale var(--duration-fast, 120ms) var(--ease-out, ease-out); }
.fl-hx-foot :is(nav a, .fl-footer__base a):is(:hover, :focus-visible)::after { scale: 1 1; }
.fl-hx-foot .fl-nav__brand:hover { color: var(--color-accent); }
@media (prefers-reduced-motion: reduce) {
  .fl-hx.is-entering :is(.fl-hx-seq > *, .fl-split > :not(.fl-hx-seq)) { animation: fl-hx-fade 120ms var(--ease-out, ease-out) backwards; }
  .fl-hx .fl-split > .fl-hx-done { animation: none; }
  .fl-hx .fl-card.fl-stat:hover { translate: none; }
  .fl-hx-foot :is(nav a, .fl-footer__base a)::after { transition: none; }
}
@keyframes fl-hx-fade { from { opacity: 0; } }
:root[data-motion="off"] .fl-hx.is-waiting :is(.fl-hx-seq > *, .fl-split > :not(.fl-hx-seq)) { opacity: 1; }
:root[data-motion="off"] .fl-hx, :root[data-motion="off"] .fl-hx * , :root[data-motion="off"] .fl-hx *::after { animation: none !important; transition: none !important; }
@media print { .fl-hx.is-waiting :is(.fl-hx-seq > *, .fl-split > :not(.fl-hx-seq)) { opacity: 1; } }
/* Grids of cards, numbers, people or footer columns (fl-hx-items) follow the heading in the same entrance, one after
   another, never more than six steps; fl-hx-last (a footer's small print) comes at the end. */
.fl-hx-items { --fl-hx-base: 1; }
.fl-hx-items > * { --fl-hx-i: 5; }
.fl-hx-items > :nth-child(1) { --fl-hx-i: 0; }
.fl-hx-items > :nth-child(2) { --fl-hx-i: 1; }
