/* Alerts and feedback: inline alerts, top banner, toasts, empty state, 404 page. Tokens only. */

/* ── Tones: each sets one color the parts below read from ── */
/* Tones outrank the base rules below, which set the neutral default. */
:is(.fl-alr, .fl-alr-toast, .fl-alr-tone-info).fl-alr-tone-info { --fl-alr-tone: var(--color-secondary, var(--color-accent)); }
:is(.fl-alr, .fl-alr-toast, .fl-alr-tone-success).fl-alr-tone-success { --fl-alr-tone: var(--color-success); }
:is(.fl-alr, .fl-alr-toast, .fl-alr-tone-warning).fl-alr-tone-warning { --fl-alr-tone: color-mix(in srgb, var(--color-danger) 50%, var(--color-success)); }
:is(.fl-alr, .fl-alr-toast, .fl-alr-tone-error).fl-alr-tone-error { --fl-alr-tone: var(--color-danger); }

/* ── Inline alert ── */
.fl-alr-stack { display: grid; gap: var(--space-4); margin: 0; padding: 0; list-style: none; }
.fl-alr {
  --fl-alr-tone: var(--color-secondary, var(--color-accent));
  display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: var(--space-3); align-items: start;
  --_r: min(var(--radius-md), 24px); --_p: var(--space-4); --_in: clamp(calc(var(--_r) * 0.5), calc(var(--_r) - var(--_p)), calc(var(--_r) * 0.75));
  padding: var(--_p) var(--space-5); border-radius: var(--_r);
  background: color-mix(in srgb, var(--fl-alr-tone) 9%, var(--color-surface));
  border: 1px solid color-mix(in srgb, var(--fl-alr-tone) 32%, var(--color-border));
  color: var(--color-text);
