  display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-3); padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-md); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px)));
