/* ── Gradient hero ── */
.fl-brd-hero {
  /* A dark panel in both themes: in light mode the text color is dark, so mix toward it; ink is the page background. */
  --fl-brd-surface: color-mix(in srgb, var(--color-text) 94%, var(--color-bg));
  --fl-brd-ink: var(--color-bg);
  --fl-brd-ink-muted: color-mix(in srgb, var(--color-bg) 72%, var(--color-text));
  --fl-brd-from: color-mix(in oklab, var(--color-secondary, var(--color-accent)) 40%, var(--color-bg));
  --fl-brd-to: color-mix(in oklab, var(--color-success) 70%, var(--color-bg));
  position: relative; isolation: isolate; overflow: hidden; display: grid; gap: var(--space-5); justify-items: start;
  padding: clamp(var(--space-6), 6vw, var(--space-9)) clamp(var(--space-5), 5vw, var(--space-8));
  border-radius: min(var(--radius-xl), 12px); background: var(--fl-brd-surface); color: var(--fl-brd-ink);
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--fl-brd-ink) 12%, transparent);
