  --fl-brd-surface: var(--color-surface-sunken);
  --fl-brd-ink: var(--color-text);
  --fl-brd-ink-muted: color-mix(in srgb, var(--color-text) 72%, var(--color-bg));
  --fl-brd-from: var(--color-secondary, var(--color-accent));
  --fl-brd-to: var(--color-success);
}
/* Soft glow in the top-right corner and a fading grid, like the original banner, drawn only with tokens. */
.fl-brd-hero::before {
  content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none;
  background:
    radial-gradient(ellipse 45% 85% at 82% 0%, color-mix(in srgb, var(--fl-brd-from) 38%, transparent), transparent 70%),
    linear-gradient(120deg, color-mix(in srgb, var(--fl-brd-from) 14%, transparent), transparent 55%);
}
.fl-brd-hero::after {
  content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none;
  background-image:
    linear-gradient(color-mix(in srgb, var(--fl-brd-ink) 6%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--fl-brd-ink) 6%, transparent) 1px, transparent 1px);
  background-size: 2.5rem 2.5rem;
  -webkit-mask-image: radial-gradient(90% 80% at 100% 0%, var(--color-text), transparent 70%);
  mask-image: radial-gradient(90% 80% at 100% 0%, var(--color-text), transparent 70%);
}
.fl-brd-eyebrow {
  display: inline-flex; align-items: center; gap: var(--space-2); width: fit-content; max-width: 100%;
  padding: var(--space-1) var(--space-3) var(--space-1) var(--space-1); border-radius: var(--radius-md);
  background: color-mix(in srgb, var(--fl-brd-ink) 9%, transparent); box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--fl-brd-ink) 14%, transparent);
  font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); color: var(--fl-brd-ink-muted); text-decoration: none;
}
a.fl-brd-eyebrow:hover { color: var(--fl-brd-ink); }
a.fl-brd-eyebrow:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-brd-eyebrow b {
  padding: 0.125rem var(--space-2); border-radius: var(--radius-sm); font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); letter-spacing: var(--tracking-wide);
  color: var(--fl-brd-surface); background: linear-gradient(135deg, var(--fl-brd-from), var(--fl-brd-to));
}
.fl-brd-hero__title {
  margin: 0; max-width: 18ch; font-family: var(--font-display); font-size: clamp(max(11px, calc(var(--text-2xl) - var(--fs-shrink, 0px))), 6vw, max(11px, calc(var(--text-3xl) - var(--fs-shrink, 0px))));
  font-weight: var(--weight-regular); line-height: var(--leading-tight); letter-spacing: var(--tracking-tight); text-wrap: balance;
  color: var(--fl-brd-ink);
}
.fl-brd-grad {
  /* Solid fallback first; the gradient replaces it where text clipping is supported. */
  color: var(--fl-brd-from); font-weight: var(--weight-semibold);
}
@supports ((-webkit-background-clip: text) or (background-clip: text)) {
  .fl-brd-grad {
    background: linear-gradient(100deg, var(--fl-brd-from) 0%, var(--fl-brd-to) 100%);
    background-size: 200% 100%;
