@keyframes fl-brd-grad-shift { to { background-position: 100% 0; } }
@media (forced-colors: active) {
  .fl-brd-grad { background: none; color: CanvasText; -webkit-text-fill-color: CanvasText; text-decoration: underline; text-decoration-thickness: 0.06em; }
  .fl-brd-hero { border: 1px solid CanvasText; }
}
.fl-brd-hero__lede { margin: 0; max-width: 56ch; font-size: max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))); line-height: var(--leading-relaxed); color: var(--fl-brd-ink-muted); }
.fl-brd-hero .fl-btn--primary { background: var(--fl-brd-ink); color: var(--fl-brd-surface); border-color: var(--fl-brd-ink); }
.fl-brd-hero .fl-btn--primary:hover { background: color-mix(in srgb, var(--fl-brd-ink) 88%, var(--fl-brd-from)); }
.fl-brd-hero .fl-btn--secondary { background: transparent; color: var(--fl-brd-ink); border-color: color-mix(in srgb, var(--fl-brd-ink) 35%, transparent); }
.fl-brd-hero .fl-btn--secondary:hover { background: color-mix(in srgb, var(--fl-brd-ink) 8%, transparent); }
.fl-brd-hero__note { margin: 0; min-height: 1.5em; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--fl-brd-ink-muted); }

/* ── Phone width ── */
@media (max-width: 30rem) {
  .fl-brd-proj__metrics { grid-template-columns: 1fr; }
  .fl-brd-appr dl { grid-template-columns: 1fr; gap: var(--space-1); }
  .fl-brd-appr dd + dt { margin-top: var(--space-2); }
  .fl-brd-appr__head .fl-brd-label:last-child { margin-left: 0; }
  .fl-brd-appr__actions .fl-btn { flex: 1 1 100%; }
