}

/* ── Reduced motion ── */
@media (prefers-reduced-motion: reduce) {
  .fl-brd-proj, .fl-brd-gauge__fill { transition: none; }
  .fl-brd-proj:hover { transform: none; }
  .fl-brd-grad { animation: none; }
}
.fl-brd-hero .fl-btn svg { width: 1.1em; height: 1.1em; flex: none; }


/* Cards: product, KPI, profile and media-list cards. Tokens only; classes start with "fl-crd-". */

/* ── Shared bits ── */
