.fl-crd-iconbtn[aria-pressed="true"] svg path { fill: currentColor; }
.fl-crd-iconbtn:focus-visible, .fl-crd-btn:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-crd-tags { display: flex; flex-wrap: wrap; gap: var(--space-2); margin: 0; padding: 0; list-style: none; }
.fl-crd-tag { padding: var(--space-1) var(--space-2); border-radius: var(--radius-sm); background: var(--color-surface-sunken); color: var(--color-text-muted); font: var(--weight-medium) max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))) / 1.4 var(--font-sans); }

/* ── Product grid ── */
.fl-crd-basket {
  display: inline-flex; align-items: center; gap: var(--space-2); min-height: var(--control-md); padding-inline: var(--space-4);
  border-radius: 999px; border: var(--surface-border, 1px solid var(--color-border)); background: var(--surface-bg, var(--color-surface)); font-weight: var(--weight-semibold); box-shadow: var(--surface-shadow, none); backdrop-filter: var(--surface-blur, none); -webkit-backdrop-filter: var(--surface-blur, none); }
