.fl-ctl-tabset--40 .fl-spec-tab { min-height: 40px; }
.fl-ctl-tabset--44 .fl-spec-tab { min-height: 44px; }
.fl-ctl-tabpanel { padding: var(--space-4); border: var(--surface-border, 1px solid var(--color-border)); border-top: 0; border-radius: 0 0 min(var(--surface-radius-sm, var(--radius-md)), 12px) min(var(--surface-radius-sm, var(--radius-md)), 12px); box-shadow: var(--surface-shadow, none); }
