/* Folding the trail back up is a text button, set apart from the trail itself. */
.fl-ctl-crumb-fold { margin-top: var(--space-2); text-decoration: underline; }

/* ── Added when the neobrutal kit folded into the catalog: full-width button, card icon tile and corner tag ── */
.fl-ctl-btn--block { width: 100%; }
.fl-ctl-card-tile {
  display: inline-grid; place-items: center; width: 2.5rem; height: 2.5rem; margin-bottom: var(--space-2);
  border: var(--edge-width, 1px) solid var(--control-edge, transparent); border-radius: var(--control-radius, var(--radius-md));
  background: var(--accent-bg, var(--color-accent)); color: var(--color-on-accent); box-shadow: var(--control-shadow, none);
}
.fl-ctl-card-tile svg { width: 1.25rem; height: 1.25rem; }
.fl-ctl-card-tag {
  position: absolute; top: calc(var(--space-3) * -1); right: var(--space-4); transform: rotate(var(--tag-tilt, 0deg));
  padding: var(--space-1) var(--space-3); border: var(--edge-width, 1px) solid var(--control-edge, transparent); border-radius: var(--control-radius-sm, var(--radius-sm));
  background: var(--color-secondary, var(--color-accent)); color: var(--color-on-secondary, var(--color-on-accent)); box-shadow: var(--control-shadow, none);
  font: var(--weight-semibold) max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))) / 1.2 var(--font-sans); letter-spacing: var(--tracking-wide); text-transform: uppercase;
}
.fl-card:has(> .fl-ctl-card-tag) { position: relative; }

/* ── c.tabs@folder: folder tabs that join the panel below. Built differently from the tab bar; edges, corners, fill and
   shadow all come from the style and surface tokens, so it looks neobrutal only under the Neo-brutalist surface. ── */
.fl-tabs--folder { display: grid; gap: 0; min-width: 0; }
.fl-tabs-folder__list {
  position: relative; z-index: 1; display: flex; gap: var(--space-2); overflow-x: auto; scrollbar-width: thin;
  padding: var(--space-1) var(--space-2) 0 0; margin-bottom: calc(var(--edge-width, 1px) * -1);
}
.fl-tabs-folder__tab {
  flex: none; min-height: var(--control-lg); padding-inline: var(--control-pad-lg, var(--space-5));
  border: var(--surface-border, 1px solid var(--color-border));
  border-radius: min(var(--surface-radius-sm, var(--radius-md)), 12px) min(var(--surface-radius-sm, var(--radius-md)), 12px) 0 0;
  background: var(--color-surface-sunken); color: var(--color-text-muted); font: var(--weight-semibold) max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))) / 1 var(--font-sans); cursor: pointer;
  transition: background-color var(--duration-fast) var(--easing), color var(--duration-fast) var(--easing);
}
.fl-tabs-folder__tab:hover:not(:disabled) { background: var(--color-secondary-surface, color-mix(in srgb, var(--color-accent) 10%, var(--color-surface))); color: var(--color-text); }
.fl-tabs-folder__tab[aria-selected="true"] { background: var(--surface-bg, var(--color-surface)); color: var(--color-text); border-bottom-color: transparent; }
.fl-tabs-folder__tab:disabled { opacity: var(--disabled-opacity, 0.55); cursor: not-allowed; }
.fl-tabs-folder__tab:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-tabs-folder__panel {
  display: grid; gap: var(--space-3); padding: var(--space-6);
  border: var(--surface-border, 1px solid var(--color-border));
  border-radius: 0 min(var(--surface-radius, var(--radius-lg)), 12px) min(var(--surface-radius, var(--radius-lg)), 12px) min(var(--surface-radius, var(--radius-lg)), 12px);
  background: var(--surface-bg, var(--color-surface)); box-shadow: var(--surface-shadow, none);
  backdrop-filter: var(--surface-blur, none); -webkit-backdrop-filter: var(--surface-blur, none);
}
.fl-tabs-folder__panel:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-tabs-folder__panel h3 { margin: 0; font-family: var(--font-display); font-size: max(11px, calc(var(--text-xl) - var(--fs-shrink, 0px))); line-height: var(--leading-snug); }
.fl-tabs-folder__panel p { margin: 0; line-height: var(--leading-relaxed); color: var(--color-text-muted); }

/* ── c.card@sticker: a tilted sticker tag, a large avatar beside a lead, a stats row and a footer. Edges, corners, fill
   and shadow come from the style and surface tokens; the hover lift and the selected shadow too. ── */
.fl-card-sticker__grid { display: grid; gap: var(--space-6); grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr)); align-items: start; margin: 0; padding: 0; list-style: none; }
.fl-card--sticker {
  position: relative; display: grid; gap: var(--space-4); align-content: start; padding: var(--space-6); color: var(--color-text);
  background: var(--surface-bg, var(--color-surface)); border: var(--surface-border, 1px solid var(--color-border));
  border-radius: min(var(--surface-radius, var(--radius-lg)), 12px); box-shadow: var(--surface-shadow, none);
  backdrop-filter: var(--surface-blur, none); -webkit-backdrop-filter: var(--surface-blur, none);
  transition: transform var(--duration-fast) var(--easing), translate var(--duration-fast) var(--easing), box-shadow var(--duration-fast) var(--easing);
}
.fl-card--sticker:hover { transform: translateY(var(--hover-lift, -2px)); translate: var(--hover-shift, none); box-shadow: var(--surface-shadow-hover, var(--surface-shadow, none)); }
.fl-card--sticker h3 { margin: 0; font-family: var(--font-display); font-size: max(11px, calc(var(--text-xl) - var(--fs-shrink, 0px))); line-height: var(--leading-tight); }
.fl-card--sticker p { margin: 0; color: var(--color-text-muted); line-height: var(--leading-normal); }
.fl-card-sticker--accent { background: var(--color-secondary-surface, color-mix(in srgb, var(--color-accent) 12%, var(--color-surface))); }
.fl-card-sticker--selected {
  background: color-mix(in srgb, var(--color-success) 14%, var(--color-surface)); border-color: var(--surface-edge, var(--color-success));
  box-shadow: var(--surface-shadow-selected, var(--surface-shadow-hover, var(--surface-shadow, none)));
}
.fl-card--sticker.is-off { opacity: var(--disabled-opacity, 0.55); }
.fl-card-sticker__tile {
  display: inline-grid; place-items: center; width: 3rem; height: 3rem;
  border: var(--edge-width, 1px) solid var(--control-edge, transparent); border-radius: min(var(--control-radius, var(--radius-md)), 12px);
  background: var(--accent-bg, var(--color-accent)); color: var(--color-on-accent); box-shadow: var(--control-shadow, none);
}
.fl-card-sticker__tile svg { width: 1.5rem; height: 1.5rem; }
.fl-card-sticker__tag {
  position: absolute; top: calc(var(--space-4) * -1); right: var(--space-4); transform: rotate(var(--tag-tilt, 6deg));
  padding: var(--space-2) var(--space-3); border: var(--edge-width, 1px) solid var(--control-edge, transparent); border-radius: var(--control-radius-sm, var(--radius-sm));
  background: var(--color-accent); color: var(--color-on-accent); box-shadow: var(--control-shadow, none);
  font: var(--weight-bold) max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))) / 1.1 var(--font-sans); letter-spacing: var(--tracking-wide); text-transform: uppercase;
}
.fl-card-sticker__person { display: flex; gap: var(--space-4); align-items: center; }
.fl-card-sticker__person h3 { font-size: max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))); }
.fl-card-sticker__lead { display: grid; gap: var(--space-1); min-width: 0; }
.fl-card-sticker__avatar {
  display: inline-grid; place-items: center; width: 4rem; height: 4rem; flex: none; border-radius: 50%;
  border: var(--edge-width, 1px) solid var(--control-edge, var(--color-border)); box-shadow: var(--control-shadow, none);
  background: var(--color-secondary-surface, color-mix(in srgb, var(--color-accent) 18%, var(--color-surface))); color: var(--color-text);
  font: var(--weight-bold) max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))) / 1 var(--font-sans);
}
.fl-card-sticker__stats {
  display: grid; grid-template-columns: repeat(3, 1fr); margin: 0;
  border: var(--surface-border, 1px solid var(--color-border)); border-radius: min(var(--surface-radius-sm, var(--radius-md)), 12px);
}
.fl-card-sticker__stats div { display: grid; gap: var(--space-1); padding: var(--space-3); text-align: center; }
.fl-card-sticker__stats div + div { border-left: var(--edge-width, 1px) solid var(--surface-edge, var(--color-border)); }
.fl-card-sticker__stats dt { order: 2; font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); color: var(--color-text-muted); text-transform: uppercase; letter-spacing: var(--tracking-wide); }
.fl-card-sticker__stats dd { margin: 0; font: var(--weight-bold) max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))) / 1 var(--font-sans); font-variant-numeric: tabular-nums; }
.fl-card-sticker__price { display: flex; align-items: baseline; gap: var(--space-2); }
.fl-card-sticker__price strong { font: var(--weight-bold) max(11px, calc(var(--text-3xl) - var(--fs-shrink, 0px))) / 1 var(--font-display); letter-spacing: var(--tracking-tight); color: var(--color-text); font-variant-numeric: tabular-nums; }
.fl-card-sticker__list { display: grid; gap: var(--space-2); margin: 0; padding: 0; list-style: none; }
.fl-card-sticker__list li { display: flex; gap: var(--space-2); align-items: center; font-weight: var(--weight-medium); }
.fl-card-sticker__list svg { width: 1.1rem; height: 1.1rem; flex: none; color: var(--color-success); }
.fl-card--sticker .fl-card-sticker__status { min-height: 1.5em; font-weight: var(--weight-semibold); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text); }
.fl-card-sticker__row { display: flex; flex-wrap: wrap; gap: var(--space-3); align-items: center; justify-content: space-between; }
/* Sticker motion: the tint and edge fade when a card is chosen, the tag settles a little further on hover, a chosen
   plan's ticks pop in one after another, and the status line fades in. */
.fl-card--sticker { transition: transform var(--duration-fast) var(--easing), translate var(--duration-fast) var(--easing), box-shadow var(--duration-fast) var(--easing), background-color var(--duration-base) var(--easing), border-color var(--duration-base) var(--easing); }
.fl-card-sticker__tag { transition: transform var(--duration-base) var(--ease-spring, var(--easing)); }
.fl-card--sticker:hover .fl-card-sticker__tag { transform: rotate(calc(var(--tag-tilt, 6deg) * 1.5)) translateY(-2px); }
.fl-card-sticker--selected .fl-card-sticker__list svg { animation: fl-card-sticker-pop var(--duration-base) var(--ease-spring, var(--easing)) both; }
.fl-card-sticker--selected .fl-card-sticker__list li:nth-child(2) svg { animation-delay: var(--stagger, 40ms); }
.fl-card-sticker--selected .fl-card-sticker__list li:nth-child(3) svg { animation-delay: calc(var(--stagger, 40ms) * 2); }
.fl-card-sticker--selected .fl-card-sticker__list li:nth-child(n + 4) svg { animation-delay: calc(var(--stagger, 40ms) * 3); }
.fl-card--sticker .fl-card-sticker__status:not(:empty) { animation: fl-card-sticker-fade var(--duration-base) var(--ease-out, var(--easing)); }
@keyframes fl-card-sticker-pop { 0% { scale: 0.6; } 60% { scale: 1.2; } 100% { scale: 1; } }
@keyframes fl-card-sticker-fade { from { opacity: 0; translate: 0 calc(var(--enter-distance, 8px) * 0.5); } }
:root[data-motion="off"] .fl-card--sticker, :root[data-motion="off"] .fl-card--sticker * { transition: none !important; animation: none !important; }
@media (max-width: 40rem) {
  .fl-card--sticker, .fl-tabs-folder__panel { padding: var(--space-5); }
}
@media (prefers-reduced-motion: reduce) {
  .fl-card--sticker, .fl-tabs-folder__tab { transition: none; }
  .fl-card--sticker:hover { transform: none; translate: none; }
  .fl-card--sticker:hover .fl-card-sticker__tag { transform: rotate(var(--tag-tilt, 6deg)); }
  .fl-card-sticker--selected .fl-card-sticker__list svg { animation: none; }
  .fl-card--sticker .fl-card-sticker__status:not(:empty) { animation: fl-card-sticker-fade-only 120ms linear; }
}
@keyframes fl-card-sticker-fade-only { from { opacity: 0; } }

/* A selectable card holding a title, a line of text and a price (a plan or box-size picker): words on the left, the
   price on the right, clear of the radio in the top-right corner. */
.fl-ctl-card:has(> .fl-in-rcard__price) { grid-template-columns: minmax(0, 1fr) auto; column-gap: var(--space-4); align-items: center; }
.fl-ctl-card:has(> .fl-in-rcard__price) > .fl-in-rcard__price { grid-column: 2; grid-row: 1 / span 2; }
.fl-ctl-card--selectable:has(> .fl-ctl-card-pick) { padding-right: calc(var(--space-3) * 2 + 1rem); }

/* Reference sheets as cards: sidebar-nav-variants, sliders-states, steppers-wizards, switches-states, tables-states, tabs-variants, tabs-vertical, text-fields-states, top-nav-variants */
.fl-ctl-spec > .fl-ctl-tabs-list { margin: 0; gap: var(--space-5); }
.fl-ctl-spec--wide > .fl-ctl-tabs-list { grid-template-columns: repeat(auto-fill, minmax(min(100%, 22rem), 1fr)); }
.fl-ctl-spec .fl-ctl-size-list li:has(> .fl-ctl-tab-sample) { flex-wrap: wrap; }
.fl-ctl-spec .fl-ctl-tab-sample { flex: 1 1 14rem; width: auto; }

/* Reference sheets as cards: ai-indicators, alerts-states, avatars-variants, badges-status, breadcrumbs-variants, buttons-variants, cards-variants, chat-bubbles */
.fl-ctl-spec > .fl-ctl-crumb-list { margin: 0; gap: var(--space-4); }

/* Reference sheets as cards: lists-rows, media-frames, modals-dialogs, motion-presets, pagination-variants, panels-drawers, popovers-menus, progress-indicators */
.fl-ctl-spec > .fl-btn { justify-self: start; }
.fl-ctl-spec > .fl-ctl-paging { margin: 0; }
/* A card is narrower than the old full-width stage: the drawer keeps at least 16rem (or three quarters of the stage) instead of shrinking to a sliver. */
.fl-ctl-spec .fl-ctl-stage--side .fl-spec-panel { left: min(62%, max(25%, calc(100% - 16rem))); }
.fl-ctl-spec .fl-ctl-stage--inline .fl-spec-panel { left: min(58%, max(25%, calc(100% - 16rem))); }


/* Dialogs: confirm dialog, form dialog, side drawer and bottom sheet (classes start with fl-dlg-). */

/* ── Page area each dialog opens from ── */
.fl-dlg-stage { display: grid; gap: var(--space-5); }
.fl-dlg-bar { display: flex; flex-wrap: wrap; gap: var(--space-3); align-items: center; justify-content: space-between; }
.fl-dlg-bar h3 { margin: 0; font-family: var(--font-display); font-size: max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))); font-weight: var(--weight-semibold); line-height: var(--leading-snug); }
.fl-dlg-list { margin: 0; padding: 0; list-style: none; display: grid; gap: var(--space-2); }
.fl-dlg-row {
  display: flex; align-items: center; gap: var(--space-3); justify-content: space-between; flex-wrap: wrap;
  padding: var(--space-3) var(--space-4); border: 1px solid var(--color-border); border-radius: var(--_in, var(--radius-md));
  background: var(--color-surface);
}
.fl-dlg-row__main { display: grid; gap: var(--space-1); min-width: 0; }
.fl-dlg-row__main strong { font-weight: var(--weight-semibold); overflow-wrap: anywhere; }
.fl-dlg-row__btn {
  all: unset; box-sizing: border-box; display: flex; width: 100%; align-items: center; justify-content: space-between; gap: var(--space-3);
  padding: var(--space-3) var(--space-4); border: 1px solid var(--color-border); border-radius: var(--_in, var(--radius-md));
  background: var(--color-surface); color: var(--color-text); cursor: pointer;
  transition: border-color var(--duration-fast) var(--easing), background-color var(--duration-fast) var(--easing);
}
.fl-dlg-row__btn:hover { border-color: var(--color-border-strong); background: var(--color-surface-sunken); }
.fl-dlg-row__btn svg { width: 1.125rem; height: 1.125rem; flex: none; color: var(--color-text-muted); }
.fl-dlg-empty {
  display: grid; gap: var(--space-2); justify-items: center; text-align: center; padding: var(--space-6) var(--space-4);
  border: 1px dashed var(--color-border-strong); border-radius: var(--_in, var(--radius-md)); color: var(--color-text-muted);
}
.fl-dlg-empty strong { color: var(--color-text); }
.fl-dlg-status { margin: 0; min-height: 1.5em; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); display: flex; flex-wrap: wrap; gap: var(--space-3); align-items: center; }
.fl-dlg-status--ok { color: var(--color-success); font-weight: var(--weight-semibold); }

/* ── Small buttons ── */
.fl-dlg-stage .fl-btn svg { width: 1.125rem; height: 1.125rem; flex: none; }
.fl-dlg-btn--sm { min-height: var(--control-sm); padding-inline: var(--control-pad-sm); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-dlg-btn--danger { background: var(--color-danger); color: var(--color-bg); border-color: var(--color-danger); }
.fl-dlg-btn--danger:hover { background: color-mix(in srgb, var(--color-danger) 88%, var(--color-text)); }
.fl-dlg-btn--ghost { background: transparent; color: var(--color-text); border-color: transparent; }
.fl-dlg-btn--ghost:hover { background: var(--color-surface-sunken); }
.fl-dlg-foot .fl-btn[aria-disabled="true"] { opacity: var(--disabled-opacity, 0.5); cursor: progress; }
.fl-dlg-link {
  all: unset; cursor: pointer; color: var(--color-accent); font-weight: var(--weight-semibold); border-radius: var(--radius-sm);
}
.fl-dlg-link:hover { text-decoration: underline; text-underline-offset: 3px; }
.fl-dlg-close {
  all: unset; box-sizing: border-box; display: grid; place-items: center; flex: none; cursor: pointer;
  width: var(--control-md); height: var(--control-md); border-radius: var(--radius-md); color: var(--color-text-muted);
}
.fl-dlg-close:hover { background: var(--color-surface-sunken); color: var(--color-text); }
.fl-dlg-close svg { width: 1.25rem; height: 1.25rem; }
.fl-dlg-link:focus-visible, .fl-dlg-close:focus-visible, .fl-dlg-row__btn:focus-visible, .fl-dlg-option:focus-visible,
.fl-dlg-panel:focus-visible, .fl-dlg-check input:focus-visible { outline: none; box-shadow: var(--focus-ring); }

/* ── Backdrop and panels (solid, never glassy) ── */
.fl-dlg-backdrop {
  position: fixed; inset: 0; z-index: 1000; display: grid; place-items: center; padding: var(--space-4);
  background: color-mix(in srgb, var(--color-text) 45%, transparent);
  animation: fl-dlg-fade var(--duration-base) var(--easing);
}
.fl-dlg-panel {
  position: relative; display: grid; gap: var(--space-4); width: 100%; max-width: 28rem; max-height: calc(100dvh - 2rem); overflow: auto;
  --_r: min(var(--radius-xl), 24px); --_p: var(--space-6); --_in: clamp(calc(var(--_r) * 0.5), calc(var(--_r) - var(--_p)), calc(var(--_r) * 0.75));
  padding: var(--_p); background: var(--color-surface); color: var(--color-text);
  border: 1px solid var(--color-border); border-radius: var(--_r);
  box-shadow: var(--surface-shadow-hover);
  animation: fl-dlg-rise var(--duration-base) var(--easing);
}
.fl-dlg-panel--wide { max-width: 32rem; }
.fl-dlg-head { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-3); }
.fl-dlg-title { margin: 0; font-family: var(--font-display); font-size: max(11px, calc(var(--text-xl) - var(--fs-shrink, 0px))); font-weight: var(--weight-semibold); line-height: var(--leading-snug); }
.fl-dlg-body { margin: 0; color: var(--color-text-muted); line-height: var(--leading-relaxed); }
.fl-dlg-foot { display: flex; flex-wrap: wrap; gap: var(--space-3); justify-content: flex-end; padding-top: var(--space-2); }
.fl-dlg-warn {
  display: flex; gap: var(--space-3); align-items: flex-start; padding: var(--space-3) var(--space-4); border-radius: var(--_in, var(--radius-md));
  background: var(--color-danger-surface); color: var(--color-danger); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); line-height: var(--leading-normal);
}
.fl-dlg-warn svg { width: 1.25rem; height: 1.25rem; flex: none; }
.fl-dlg-icon {
  display: grid; place-items: center; width: 2.75rem; height: 2.75rem; border-radius: 50%; flex: none;
  background: var(--color-danger-surface); color: var(--color-danger);
}
.fl-dlg-icon svg { width: 1.375rem; height: 1.375rem; }

/* ── Form fields inside dialogs ── */
.fl-dlg-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-4); }
.fl-dlg-error { margin: 0; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-danger); font-weight: var(--weight-medium); }
.fl-input[aria-invalid="true"] { border-color: var(--color-danger); }
.fl-dlg-select { position: relative; display: block; }
.fl-dlg-select select { appearance: none; -webkit-appearance: none; padding-right: 2.25rem; cursor: pointer; }
.fl-dlg-select::after {
  content: ""; position: absolute; right: 0.5rem; top: 50%; width: 0.5rem; height: 0.5rem; pointer-events: none;
  border-right: 2px solid var(--color-text-muted); border-bottom: 2px solid var(--color-text-muted);
  transform: translate(-0.125rem, -70%) rotate(45deg);
}
.fl-dlg-check { display: flex; gap: var(--space-3); align-items: center; font-weight: var(--weight-medium); cursor: pointer; }
.fl-dlg-check input { width: 1.125rem; height: 1.125rem; accent-color: var(--color-accent); margin: 0; border-radius: var(--radius-sm); }

/* ── Side drawer ── */
.fl-dlg-backdrop--drawer { place-items: stretch end; padding: 0; }
.fl-dlg-drawer {
  display: grid; grid-template-rows: auto 1fr auto; width: min(26rem, 100vw); height: 100dvh;
  background: var(--color-surface); color: var(--color-text); border-left: 1px solid var(--color-border);
  box-shadow: var(--surface-shadow-hover);
  animation: fl-dlg-slide-in var(--duration-slow, var(--duration-base)) var(--easing);
}
