.fl-dlg-drawer__head { display: flex; align-items: flex-start; justify-content: space-between; gap: var(--space-3); padding: var(--space-5) var(--space-5) var(--space-4); border-bottom: 1px solid var(--color-border); }
.fl-dlg-drawer__body { overflow: auto; padding: var(--space-5); display: grid; gap: var(--space-5); align-content: start; }
.fl-dlg-drawer__foot { display: flex; gap: var(--space-3); justify-content: flex-end; padding: var(--space-4) var(--space-5); border-top: 1px solid var(--color-border); background: var(--color-surface-sunken); }
.fl-dlg-details { margin: 0; display: grid; grid-template-columns: auto 1fr; gap: var(--space-2) var(--space-5); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
