  --_r: min(var(--radius-xl), 24px); --_p: var(--space-4); --_in: clamp(calc(var(--_r) * 0.5), calc(var(--_r) - var(--_p)), calc(var(--_r) * 0.75));
  width: 100%; max-width: 24rem; margin-inline: auto; padding: var(--space-5) var(--_p); display: grid; gap: var(--space-4);
