  min-height: var(--control-sm); padding-inline: var(--space-2); border-radius: var(--radius-md); color: var(--color-text-muted); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); font-weight: var(--weight-semibold);
