.fl-dsp-ann a:focus-visible, .fl-dsp-pill:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-dsp-x {
  display: inline-grid; place-items: center; width: var(--control-sm); height: var(--control-sm); flex: none; border: 0;
  border-radius: var(--radius-sm); background: transparent; color: inherit; cursor: pointer; opacity: 0.85;
  transition: background-color var(--duration-fast) var(--easing);
}
.fl-dsp-x:hover { opacity: 1; background: color-mix(in srgb, currentColor 14%, transparent); }
.fl-dsp-x svg { width: 1rem; height: 1rem; }
.fl-dsp-status { margin: 0; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }
.fl-dsp-empty { margin: 0; padding: var(--space-6); text-align: center; border: 1px dashed var(--color-border-strong); border-radius: var(--radius-md); color: var(--color-text-muted); }
.fl-dsp-spin { width: 1rem; height: 1rem; border-radius: 50%; border: 2px solid currentColor; border-right-color: transparent; animation: fl-dsp-spin 0.8s linear infinite; }
@keyframes fl-dsp-spin { to { transform: rotate(360deg); } }
.fl-dsp-toolbar { display: flex; flex-wrap: wrap; gap: var(--space-3); align-items: center; justify-content: space-between; margin-bottom: var(--space-5); }

/* ── Activity timeline ── */
.fl-dsp-tl-card { padding: var(--space-6); gap: var(--space-5); }
