.fl-dsp-tl-day { margin: 0 0 var(--space-3); font: var(--weight-semibold) max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))) / 1 var(--font-sans); letter-spacing: var(--tracking-wide); text-transform: uppercase; color: var(--color-text-muted); }
.fl-dsp-tl-days { display: grid; gap: var(--space-6); }
.fl-dsp-tl { margin: 0; padding: 0; list-style: none; display: grid; }
