.fl-dsp-tone-danger { --fl-dsp-tone: var(--color-danger); }
.fl-dsp-tone-muted { --fl-dsp-tone: var(--color-text-muted); }
.fl-dsp-tl__body { display: grid; gap: var(--space-1); padding-top: var(--space-1); min-width: 0; }
.fl-dsp-tl__line { margin: 0; display: flex; flex-wrap: wrap; justify-content: space-between; gap: var(--space-1) var(--space-3); line-height: var(--leading-snug); }
.fl-dsp-tl__line strong { font-weight: var(--weight-semibold); }
.fl-dsp-tl__line time { font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); white-space: nowrap; font-variant-numeric: tabular-nums; }
.fl-dsp-tl__note { margin: 0; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); line-height: var(--leading-normal); }
.fl-dsp-tl__quote { margin: var(--space-2) 0 0; padding: var(--space-3) var(--space-4); border-radius: var(--radius-md); background: var(--color-surface-sunken); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); line-height: var(--leading-normal); }
.fl-dsp-tl-more { display: flex; flex-wrap: wrap; gap: var(--space-3); align-items: center; justify-content: center; padding-top: var(--space-2); border-top: 1px solid var(--color-border); }
.fl-dsp-tl-more .fl-dsp-btn { margin-top: var(--space-4); }
.fl-dsp-tl-more .fl-dsp-status, .fl-dsp-tl-more .fl-dsp-err { margin-top: var(--space-4); }

/* ── Details list ── */
.fl-dsp-dl-card { padding: 0; gap: 0; overflow: hidden; }
.fl-dsp-dl-head { display: flex; flex-wrap: wrap; gap: var(--space-3); align-items: center; justify-content: space-between; padding: var(--space-5) var(--space-6); border-bottom: 1px solid var(--color-border); }
