.fl-dsp-dl__row:last-child { border-bottom: 0; }
.fl-dsp-dl__row:nth-child(even) { background: color-mix(in srgb, var(--color-surface-sunken) 55%, transparent); }
.fl-dsp-dl__row dt { font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); font-weight: var(--weight-semibold); color: var(--color-text-muted); padding-top: var(--space-2); }
.fl-dsp-dl__row dd { margin: 0; min-width: 0; display: flex; flex-wrap: wrap; align-items: flex-start; justify-content: space-between; gap: var(--space-2) var(--space-4); padding-top: var(--space-2); line-height: var(--leading-normal); overflow-wrap: anywhere; }
.fl-dsp-dl__row dd > :first-child { flex: 1 1 12rem; min-width: 0; }
.fl-dsp-dl__row dd > .fl-dsp-dl__actions { margin-top: calc(-1 * var(--space-2)); }
.fl-dsp-dl__row--editing dd { padding-top: 0; }
.fl-dsp-dl__actions { display: flex; gap: var(--space-2); justify-content: flex-end; flex: none; }
.fl-dsp-dl__edit { display: grid; gap: var(--space-2); flex: 1 1 100%; }
.fl-dsp-dl__edit .fl-input { min-height: var(--control-sm); height: var(--control-sm); padding-block: var(--space-2); }
.fl-dsp-dl__edit .fl-input[aria-invalid="true"] { border-color: var(--color-danger); background: color-mix(in srgb, var(--color-danger-surface) 60%, var(--color-surface)); }
.fl-dsp-err { margin: 0; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-danger); line-height: var(--leading-normal); }
.fl-dsp-ref { display: inline-flex; align-items: center; gap: var(--space-2); font-family: var(--font-mono); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-dsp-ok { color: var(--color-success); }
.fl-dsp-dl-foot { padding: var(--space-3) var(--space-6); border-top: 1px solid var(--color-border); background: var(--color-surface-sunken); min-height: 2.75rem; }

/* ── Stats compare ── */
.fl-dsp-stats { display: grid; grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr)); gap: var(--space-4); margin: 0; padding: 0; list-style: none; }
.fl-dsp-stat { display: grid; align-content: start; gap: var(--space-2); padding: var(--space-5); background: var(--surface-bg, var(--color-surface)); border: var(--surface-border, 1px solid var(--color-border)); border-radius: min(var(--surface-radius, var(--radius-lg)), 12px); box-shadow: var(--surface-shadow, none); }
.fl-dsp-stat__label { margin: 0; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); font-weight: var(--weight-medium); }
.fl-dsp-stat__value { margin: 0; display: flex; flex-wrap: wrap; align-items: baseline; gap: var(--space-2) var(--space-3); }
.fl-dsp-stat__value strong { font: var(--weight-bold) max(11px, calc(var(--text-2xl) - var(--fs-shrink, 0px))) / 1.1 var(--font-display); font-variant-numeric: tabular-nums; }
.fl-dsp-delta { display: inline-flex; align-items: center; gap: var(--space-1); padding: var(--space-1) var(--space-2); border-radius: 999px; font: var(--weight-semibold) max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))) / 1.2 var(--font-sans); font-variant-numeric: tabular-nums; }
.fl-dsp-delta svg { width: 0.85rem; height: 0.85rem; }
.fl-dsp-delta--good { color: var(--color-success); background: color-mix(in srgb, var(--color-success) 13%, transparent); }
.fl-dsp-delta--bad { color: var(--color-danger); background: color-mix(in srgb, var(--color-danger) 12%, transparent); }
.fl-dsp-delta--flat { color: var(--color-text-muted); background: var(--color-surface-sunken); }
.fl-dsp-stat__prev { margin: 0; font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }
.fl-dsp-spark { display: block; width: 100%; height: 3rem; margin-top: var(--space-2); overflow: visible; }
.fl-dsp-spark__line { fill: none; stroke: var(--color-accent); stroke-width: 2; stroke-linecap: round; stroke-linejoin: round; vector-effect: non-scaling-stroke; }
.fl-dsp-spark__area { fill: color-mix(in srgb, var(--color-accent) 14%, transparent); stroke: none; }
.fl-dsp-stats--loading .fl-dsp-stat { opacity: 0.55; transition: opacity var(--duration-base) var(--easing); }

/* ── Progress ── */
.fl-dsp-prog-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-5); }
.fl-dsp-prog-card { gap: var(--space-4); }
.fl-dsp-bar-row { display: grid; gap: var(--space-2); }
.fl-dsp-bar-row__top { display: flex; justify-content: space-between; gap: var(--space-3); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-dsp-bar-row__top span:last-child { color: var(--color-text-muted); font-variant-numeric: tabular-nums; }
.fl-dsp-track { position: relative; display: flex; height: 0.625rem; border-radius: var(--pill-radius, 999px); background: var(--color-surface-sunken); border: 1px solid var(--color-border); overflow: hidden; box-shadow: var(--well-shadow, none); }
.fl-dsp-fill { height: 100%; border-radius: 999px; background: var(--color-accent); transition: width var(--duration-base) var(--easing); }
.fl-dsp-fill--success { background: var(--color-success); }
.fl-dsp-fill--danger { background: var(--color-danger); }
.fl-dsp-steps { display: grid; grid-auto-flow: column; grid-auto-columns: minmax(0, 1fr); gap: var(--space-2); margin: 0; padding: 0; list-style: none; }
.fl-dsp-steps li { display: grid; gap: var(--space-2); font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); color: var(--color-text-muted); min-width: 0; }
.fl-dsp-steps li::before { content: ""; height: 0.375rem; border-radius: 999px; background: var(--color-surface-sunken); border: 1px solid var(--color-border); transition: background-color var(--duration-base) var(--easing); }
.fl-dsp-steps li[data-state="done"]::before { background: var(--color-accent); border-color: var(--color-accent); }
.fl-dsp-steps li[data-state="current"]::before { background: color-mix(in srgb, var(--color-accent) 45%, var(--color-surface)); border-color: var(--color-accent); }
.fl-dsp-steps li[data-state="current"] { color: var(--color-text); font-weight: var(--weight-semibold); }
.fl-dsp-seg { transition: width var(--duration-base) var(--easing); }
.fl-dsp-seg + .fl-dsp-seg { border-left: 2px solid var(--color-surface); }
.fl-dsp-legend { display: flex; flex-wrap: wrap; gap: var(--space-2) var(--space-4); margin: 0; padding: 0; list-style: none; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-dsp-legend li { display: inline-flex; align-items: center; gap: var(--space-2); }
.fl-dsp-legend i { width: 0.7rem; height: 0.7rem; border-radius: var(--radius-sm); flex: none; }
.fl-dsp-legend span { color: var(--color-text-muted); font-variant-numeric: tabular-nums; }
.fl-dsp-c1 { background: var(--color-accent); }
.fl-dsp-c2 { background: var(--color-secondary, color-mix(in srgb, var(--color-accent) 55%, var(--color-success))); }
.fl-dsp-c3 { background: var(--color-success); }
.fl-dsp-c4 { background: color-mix(in srgb, var(--color-text-muted) 70%, transparent); }
.fl-dsp-ring { display: flex; gap: var(--space-5); align-items: center; flex-wrap: wrap; }
.fl-dsp-ring svg { width: 7.5rem; height: 7.5rem; flex: none; transform: rotate(-90deg); }
.fl-dsp-ring__bg { fill: none; stroke: var(--color-surface-sunken); stroke-width: 10; }
.fl-dsp-ring__fg { fill: none; stroke: var(--color-accent); stroke-width: 10; stroke-linecap: round; transition: stroke-dashoffset var(--duration-base) var(--easing); }
.fl-dsp-ring__wrap { position: relative; display: grid; place-items: center; }
.fl-dsp-ring__wrap > strong { position: absolute; font: var(--weight-bold) max(11px, calc(var(--text-xl) - var(--fs-shrink, 0px))) / 1 var(--font-display); font-variant-numeric: tabular-nums; }
.fl-dsp-ring__text { display: grid; gap: var(--space-2); flex: 1 1 10rem; }

/* ── Announcements ── */
.fl-dsp-ann { background: var(--color-text); color: var(--color-bg); }
.fl-dsp-ann__row { display: flex; align-items: center; gap: var(--space-3); max-width: var(--content-max, 72rem); margin-inline: auto; padding: var(--space-2) var(--space-5); min-height: var(--control-md); }
.fl-dsp-ann__msg { flex: 1; margin: 0; text-align: center; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); line-height: var(--leading-snug); }
.fl-dsp-ann a { color: inherit; font-weight: var(--weight-semibold); text-underline-offset: 3px; border-radius: var(--radius-sm); margin-left: var(--space-2); white-space: nowrap; }
.fl-dsp-pill {
  display: inline-flex; align-items: center; gap: var(--space-2); padding: var(--space-1) var(--space-3) var(--space-1) var(--space-1);
  border-radius: 999px; border: 1px solid var(--color-border); background: var(--color-surface); color: var(--color-text);
  font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); text-decoration: none; transition: border-color var(--duration-fast) var(--easing);
