  position: absolute; top: 50%; right: var(--space-2); transform: translateY(-50%);
  min-height: var(--control-sm); padding-inline: var(--space-3); border: 0; border-radius: var(--radius-sm);
  background: transparent; color: var(--color-accent); font: var(--weight-semibold) max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))) / 1 var(--font-sans); cursor: pointer;
}
