/* ── Settings: two-column groups ── */
.fl-frm-settings { display: grid; gap: 0; }
.fl-frm-group { display: grid; grid-template-columns: minmax(0, 15rem) minmax(0, 1fr); gap: var(--space-7); padding-block: var(--space-7); border-top: 1px solid var(--color-border); }
