.fl-frm-danger { display: flex; flex-wrap: wrap; justify-content: space-between; align-items: center; gap: var(--space-4); padding: var(--space-5); border: 1px solid color-mix(in srgb, var(--color-danger) 40%, transparent); border-radius: min(var(--radius-lg), 12px); background: color-mix(in srgb, var(--color-danger-surface) 50%, var(--color-surface)); }
.fl-frm-danger p { margin: 0; }
.fl-frm-btn--danger { background: var(--color-danger); color: var(--color-on-accent); border-color: var(--color-danger); }
.fl-frm-btn--danger:hover { background: color-mix(in srgb, var(--color-danger) 85%, var(--color-text)); }
.fl-frm-btn--danger-outline { background: var(--color-surface); color: var(--color-danger); border-color: color-mix(in srgb, var(--color-danger) 50%, transparent); }
.fl-frm-savebar {
  position: sticky; bottom: var(--space-4); display: flex; flex-wrap: wrap; align-items: center; justify-content: space-between; gap: var(--space-3);
  margin-top: var(--space-5); padding: var(--space-3) var(--space-4); border: var(--surface-border, 1px solid var(--color-border)); border-radius: min(var(--radius-lg), 12px);
  background: var(--surface-bg, var(--color-surface)); box-shadow: var(--surface-shadow-hover, var(--surface-shadow, none)); backdrop-filter: var(--surface-blur, none); -webkit-backdrop-filter: var(--surface-blur, none);
}
.fl-frm-dirty { display: inline-flex; align-items: center; gap: var(--space-2); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); font-weight: var(--weight-semibold); color: var(--color-text); }
.fl-frm-dirty::before { content: ""; width: 0.5rem; height: 0.5rem; border-radius: 50%; background: var(--color-secondary, var(--color-accent)); }
.fl-frm-saved { display: inline-flex; align-items: center; gap: var(--space-2); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); font-weight: var(--weight-semibold); color: var(--color-success); }
.fl-frm-saved svg { width: 1rem; height: 1rem; }
.fl-frm-avatar-row { display: flex; align-items: center; gap: var(--space-4); }
.fl-frm-avatar-row .fl-person__avatar { width: 3.5rem; height: 3.5rem; font-size: max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))); }

/* Confirmation dialog */
.fl-frm-backdrop { position: fixed; inset: 0; z-index: 50; display: grid; place-items: center; padding: var(--space-4); background: color-mix(in srgb, var(--color-text) 45%, transparent); animation: fl-frm-fade var(--duration-base) var(--easing); }
.fl-frm-dialog {
  width: 100%; max-width: 28rem; display: grid; gap: var(--space-4); padding: var(--space-6);
  background: var(--color-surface); border: 1px solid var(--color-border); border-radius: min(var(--radius-xl), 12px); box-shadow: var(--surface-shadow-hover, var(--surface-shadow, none));
