.fl-frm-step-title svg { width: 0.9rem; height: 0.9rem; color: var(--color-success); }
.fl-frm-nav { display: flex; justify-content: space-between; gap: var(--space-3); padding-top: var(--space-4); border-top: 1px solid var(--color-border); }
.fl-frm-nav .fl-btn--primary { margin-left: auto; }
