.fl-frm-review > div { display: grid; grid-template-columns: minmax(0, 10rem) minmax(0, 1fr) auto; gap: var(--space-3); align-items: baseline; padding: var(--space-3) var(--space-4); }
.fl-frm-review > div + div { border-top: 1px solid var(--color-border); }
.fl-frm-review dt { font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }
.fl-frm-review dd { margin: 0; font-weight: var(--weight-medium); overflow-wrap: anywhere; }
.fl-frm-edit { padding: 0; border: 0; background: none; font: var(--weight-semibold) max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))) / 1.4 var(--font-sans); color: var(--color-accent); cursor: pointer; border-radius: var(--radius-sm); }
.fl-frm-edit:hover { text-decoration: underline; text-underline-offset: 3px; }
.fl-frm-edit:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-frm-pane { display: grid; gap: var(--space-4); }
.fl-frm-pane h3 { margin: 0; font-family: var(--font-display); font-size: max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))); line-height: var(--leading-snug); }
.fl-frm-pane h3:focus { outline: none; }

/* ── Filter bar and list ── */
.fl-frm-bar { display: grid; grid-template-columns: var(--fl-frm-cols, minmax(0, 1fr) minmax(0, 12rem) minmax(0, 12rem)); gap: var(--space-3); align-items: end; }
.fl-frm-search { position: relative; }
.fl-frm-search > svg { position: absolute; left: var(--space-3); top: 50%; width: 1.125rem; height: 1.125rem; transform: translateY(-50%); color: var(--color-text-muted); pointer-events: none; }
.fl-frm-search .fl-input { padding-left: 2.5rem; padding-right: 2.5rem; }
.fl-frm-search .fl-input::-webkit-search-cancel-button { display: none; }
.fl-frm-clear-x { position: absolute; right: var(--space-2); top: 50%; transform: translateY(-50%); display: grid; place-items: center; width: var(--control-sm); height: var(--control-sm); padding: 0; border: 0; border-radius: var(--radius-sm); background: transparent; color: var(--color-text-muted); cursor: pointer; }
.fl-frm-clear-x:hover { color: var(--color-text); background: var(--color-surface-sunken); }
.fl-frm-clear-x:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-frm-clear-x svg { width: 1rem; height: 1rem; }
.fl-frm-chipbar { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); min-height: var(--control-sm); margin-top: var(--space-4); }
.fl-frm-chips { display: flex; flex-wrap: wrap; gap: var(--space-2); margin: 0; padding: 0; list-style: none; }
.fl-frm-chip {
  display: inline-flex; align-items: center; gap: var(--space-1); min-height: var(--control-sm); padding: 0 var(--space-1) 0 var(--space-3);
  border-radius: 999px; background: var(--color-secondary-surface, color-mix(in srgb, var(--color-accent) 12%, var(--color-surface))); color: var(--color-text);
  border: 1px solid var(--color-secondary-border, color-mix(in srgb, var(--color-accent) 30%, transparent)); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); font-weight: var(--weight-medium);
}
.fl-frm-chip button { display: grid; place-items: center; width: 1.5rem; height: 1.5rem; padding: 0; border: 0; border-radius: 50%; background: transparent; color: var(--color-text-muted); cursor: pointer; }
.fl-frm-chip button:hover { background: var(--color-secondary-surface, color-mix(in srgb, var(--color-accent) 18%, transparent)); color: var(--color-text); }
.fl-frm-chip button:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-frm-chip svg { width: 0.875rem; height: 0.875rem; }
.fl-frm-textbtn { padding: var(--space-1) var(--space-2); border: 0; border-radius: var(--radius-sm); background: none; color: var(--color-accent); font: var(--weight-semibold) max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))) / 1.4 var(--font-sans); cursor: pointer; }
.fl-frm-textbtn:hover { text-decoration: underline; text-underline-offset: 3px; }
.fl-frm-textbtn:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-frm-quick { display: flex; flex-wrap: wrap; gap: var(--space-2); margin-top: var(--space-3); }
.fl-frm-quick button { min-height: var(--control-sm); padding-inline: var(--space-3); border-radius: 999px; border: 1px solid var(--color-border); background: var(--color-surface); color: var(--color-text-muted); font: var(--weight-medium) max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))) / 1 var(--font-sans); cursor: pointer; transition: border-color var(--duration-fast) var(--easing), color var(--duration-fast) var(--easing); }
.fl-frm-quick button:hover { border-color: var(--color-border-strong); color: var(--color-text); }
.fl-frm-quick button[aria-pressed="true"] { border-color: var(--color-accent); color: var(--color-accent); background: color-mix(in srgb, var(--color-accent) 8%, var(--color-surface)); }
.fl-frm-quick button:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-frm-count { margin: var(--space-5) 0 var(--space-3); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }
.fl-frm-results { display: grid; margin: 0; padding: 0; list-style: none; border: 1px solid var(--color-border); border-radius: min(var(--radius-lg), 12px); background: var(--color-surface); overflow: hidden; }
.fl-frm-results li { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: var(--space-4); align-items: center; padding: var(--space-4); }
.fl-frm-results li + li { border-top: 1px solid var(--color-border); }
.fl-frm-results strong { display: block; }
.fl-frm-results .fl-meta { display: block; margin-top: var(--space-1); }
.fl-frm-price { font-weight: var(--weight-semibold); font-variant-numeric: tabular-nums; white-space: nowrap; }
.fl-frm-status { display: inline-block; margin-top: var(--space-1); font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); font-weight: var(--weight-semibold); color: var(--color-success); }
.fl-frm-status[data-open="false"] { color: var(--color-text-muted); }
.fl-frm-empty { display: grid; gap: var(--space-3); justify-items: center; text-align: center; padding: var(--space-8) var(--space-5); border: 1px dashed var(--color-border-strong); border-radius: min(var(--radius-lg), 12px); }
.fl-frm-empty h3 { margin: 0; font-family: var(--font-display); font-size: max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))); }
.fl-frm-empty .fl-text { max-width: 24rem; }
mark.fl-frm-hit { background: color-mix(in srgb, var(--color-accent) 22%, transparent); color: inherit; border-radius: var(--radius-sm); padding-inline: 1px; }

/* ── Motion ── */
@media (prefers-reduced-motion: reduce) {
  .fl-frm-strength span, .fl-frm-option, .fl-frm-switch, .fl-frm-switch::after, .fl-frm-steps li::before, .fl-frm-quick button { transition: none; }
  .fl-frm-backdrop, .fl-frm-dialog { animation: none; }
}

/* ── Phones ── */
@media (max-width: 860px) {
  .fl-frm-group { grid-template-columns: minmax(0, 1fr); gap: var(--space-4); padding-block: var(--space-6); }
  .fl-frm-bar { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
  .fl-frm-bar > :first-child { grid-column: 1 / -1; }
}
@media (max-width: 480px) {
  .fl-frm-bar { grid-template-columns: minmax(0, 1fr); }
  .fl-frm-review > div { grid-template-columns: minmax(0, 1fr) auto; }
  .fl-frm-review dt { grid-column: 1 / -1; }
  .fl-frm-results li { grid-template-columns: auto minmax(0, 1fr); }
  .fl-frm-results li > :last-child { grid-column: 2; }
  .fl-frm-steps li { font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); }
  .fl-frm-danger { flex-direction: column; align-items: stretch; }
  .fl-frm-savebar .fl-btn { flex: 1 1 auto; }
  .fl-frm-nav .fl-btn { flex: 1 1 0; }
}


/* Inputs (category "forms"): file upload, range sliders, quantity steppers, button groups, radio cards, textareas and selects. Classes start with "fl-in-". Tokens only. */

/* ── Shared ── */
.fl-in-panel { gap: var(--space-5); }
.fl-in-stack { display: grid; gap: var(--space-6); }
.fl-in-error { margin: 0; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); line-height: var(--leading-normal); color: var(--color-danger); }
.fl-in-errors {
  margin: 0; padding: var(--space-3) var(--space-4); list-style: none; display: grid; gap: var(--space-1);
  border-radius: var(--radius-md); background: var(--color-danger-surface); color: var(--color-danger); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); line-height: var(--leading-normal);
}
.fl-in-empty {
  margin: 0; padding: var(--space-4); border: 1px dashed var(--color-border); border-radius: var(--radius-md);
  color: var(--color-text-muted); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); text-align: center;
}
.fl-in-fieldset { margin: 0; padding: 0; border: 0; min-width: 0; display: grid; gap: var(--space-3); }
.fl-in-fieldset legend { padding: 0; margin-bottom: var(--space-3); font-weight: var(--weight-semibold); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-in-panel .fl-input[aria-invalid="true"], .fl-in-trigger[aria-invalid="true"], .fl-in-search .fl-input[aria-invalid="true"] {
  border-color: var(--color-danger); background: color-mix(in srgb, var(--color-danger-surface) 60%, var(--color-surface));
