.fl-in-listbox { right: 0; max-height: 16rem; overflow-y: auto; overscroll-behavior: contain; min-width: 0; max-width: none; }
.fl-in-option {
  display: flex; align-items: center; gap: var(--space-3); padding: var(--space-2) var(--space-3); border-radius: var(--radius-sm); cursor: pointer;
}
.fl-in-option__text { display: grid; gap: 0; flex: 1; min-width: 0; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-in-option__text .fl-meta { font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); }
