.fl-in-option[aria-selected="true"] { font-weight: var(--weight-semibold); }
.fl-in-option__check { display: inline-grid; color: var(--color-accent); }
.fl-in-option__check svg { width: 1rem; height: 1rem; }
.fl-in-noresult { padding: var(--space-4) var(--space-3); color: var(--color-text-muted); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); text-align: center; }
.fl-in-search { position: relative; }
.fl-in-search > svg:first-child { position: absolute; left: var(--space-3); top: 50%; width: 1.125rem; height: 1.125rem; transform: translateY(-50%); color: var(--color-text-muted); pointer-events: none; }
.fl-in-search .fl-input { padding-left: 2.5rem; padding-right: 2.25rem; }
/* Select motion: the list opens with a short fade and scale from the field; the chevron turns (on a native select too,
   where the browser reports it open); the highlight eases between options and a chosen tick pops in; errors and the
   saved line fade in. */
.fl-in-listbox { transform-origin: top center; animation: fl-in-list-open var(--duration-base) var(--ease-out, var(--easing)); }
@keyframes fl-in-list-open { from { opacity: 0; transform: translateY(calc(var(--space-1) * -1)) scale(0.97); } }
.fl-in-trigger { transition: border-color var(--duration-fast) var(--easing), box-shadow var(--duration-fast) var(--easing), background-color var(--duration-fast) var(--easing); }
.fl-in-trigger:active:not(:disabled) { background: color-mix(in srgb, var(--color-text) 4%, var(--control-bg, var(--color-surface))); }
.fl-in-chev { transition: transform var(--duration-base) var(--ease-out, var(--easing)), color var(--duration-fast) var(--easing); }
