/* ── Phones ── */
@container specimen (max-width: 560px) {
  .fl-in-selects { grid-template-columns: minmax(0, 1fr); }
  .fl-in-drop { padding: var(--space-6) var(--space-4); }
  .fl-in-file { padding: var(--space-3); gap: var(--space-2); }
  .fl-in-row { flex-wrap: wrap; }
  .fl-in-rcard { grid-template-columns: auto minmax(0, 1fr); padding: var(--space-4); }
  .fl-in-rcard__price { grid-column: 2; justify-items: start; text-align: left; display: flex; gap: var(--space-1); align-items: baseline; }
  .fl-in-minmax { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); }
  .fl-in-minmax__dash { display: none; }
  .fl-in-split-wrap { justify-self: stretch; }
