/* Checkboxes and radios: the browser's own controls, tinted to the app's accent. */
.fl-ctl-check { width: 18px; height: 18px; accent-color: var(--color-accent); cursor: pointer; }
.fl-ctl-check:disabled { cursor: not-allowed; opacity: 0.6; }
.fl-ctl-choice-list { display: grid; gap: var(--space-3); margin: 0; padding: 0; list-style: none; }
.fl-ctl-choice { display: grid; grid-template-columns: auto 1fr; gap: var(--space-3); align-items: start; padding: var(--space-4); border: var(--edge-width, 1px) solid var(--control-edge, var(--color-border)); border-radius: var(--control-radius, var(--radius-md)); cursor: pointer; }
