.fl-ctl-switch--16 { --fl-switch-h: 16px; }
.fl-ctl-switch--18 { --fl-switch-h: 18px; }
.fl-ctl-switch--20 { --fl-switch-h: 20px; }
.fl-ctl-switch--24 { --fl-switch-h: 24px; }
.fl-ctl-switch--32 { --fl-switch-h: 32px; }
