.fl-ctl-switch input:disabled { cursor: not-allowed; }
.fl-ctl-switch-track { pointer-events: none; display: inline-flex; align-items: center; width: calc(var(--fl-switch-h) * 1.75); height: var(--fl-switch-h); padding: calc(var(--fl-switch-h) * 0.1); border-radius: 999px; background: var(--color-border-strong, #9aa1ad); transition: background var(--duration-fast) var(--easing); box-shadow: var(--well-shadow, none); }
