.fl-ctl-setting-list { display: grid; gap: var(--space-3); margin: 0; padding: 0; list-style: none; }
.fl-ctl-setting-list li { display: flex; align-items: center; justify-content: space-between; gap: var(--space-5); padding: var(--space-4); border: var(--surface-border, 1px solid var(--color-border)); border-radius: min(var(--surface-radius-sm, var(--radius-md)), 12px); }
.fl-ctl-setting-list strong { display: block; }
