input.fl-ctl-field--32 { height: 32px; min-height: 32px; padding-inline: var(--space-3); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
input.fl-ctl-field--40 { height: 40px; min-height: 40px; padding-inline: var(--space-3); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
input.fl-ctl-field--44 { height: 44px; min-height: 44px; padding-inline: var(--space-4); }
input.fl-ctl-field--48 { height: 48px; min-height: 48px; padding-inline: var(--space-4); }
