.fl-ctl-size-list li > .fl-ctl-field { flex: none; width: 17rem; }

/* ── Checkbox and radio sizes: they sit beside text, so the scale is small ── */
.fl-ctl-check--14 { width: 14px; height: 14px; }
.fl-ctl-check--16 { width: 16px; height: 16px; }
.fl-ctl-check--18 { width: 18px; height: 18px; }
.fl-ctl-check--20 { width: 20px; height: 20px; }
.fl-ctl-check--24 { width: 24px; height: 24px; }

/* ── Combo box: the field with its chevron sitting inside ── */
/* Select and combo box: the chevron is drawn, not the browser's, and sits 8px from the right edge. */
.fl-ctl-combo, .fl-ctl-select { position: relative; display: block; }
.fl-ctl-combo svg, .fl-ctl-select svg { position: absolute; right: 8px; top: 50%; width: 1rem; height: 1rem; transform: translateY(-50%); pointer-events: none; color: var(--color-text-muted); }
.fl-ctl-combo .fl-ctl-field, .fl-ctl-select select { padding-right: calc(8px + 1rem + var(--space-2)); }
.fl-ctl-select select { appearance: none; -webkit-appearance: none; cursor: pointer; }

/* ── The open menu, drawn in place so it can be read ── */
.fl-ctl-menu { max-width: 22rem; margin: 0; padding: var(--space-2); list-style: none; border: var(--surface-border, 1px solid var(--color-border)); border-radius: min(var(--surface-radius-sm, var(--radius-md)), 12px); background: var(--surface-bg, var(--color-surface)); box-shadow: var(--surface-shadow-overlay, var(--shadow-md, 0 8px 24px rgba(0,0,0,.12))); backdrop-filter: var(--surface-blur, none); -webkit-backdrop-filter: var(--surface-blur, none); }
.fl-ctl-menu li { display: flex; align-items: center; gap: var(--space-2); padding: var(--space-2) var(--space-3); border-radius: var(--radius-sm); }
