.fl-ctl-menu li[aria-selected="true"] { font-weight: var(--weight-semibold); }
.fl-ctl-menu-tick { display: inline-grid; place-items: center; width: 1.1em; }
.fl-ctl-menu-tick svg { width: 1em; height: 1em; }

/* ── Sliders: the value is always written out beside the track ── */
