.fl-ctl-range { width: 100%; accent-color: var(--color-accent); }
.fl-ctl-range.is-focus { outline: none; box-shadow: var(--focus-ring); border-radius: 999px; }
.fl-ctl-range:disabled { opacity: 0.55; cursor: not-allowed; }
.fl-ctl-slider-value { font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }
.fl-ctl-slider--range { max-width: 26rem; }
.fl-ctl-slider-ends { display: flex; justify-content: space-between; }

/* ── Chips: a filter is a button, a label is not ── */
.fl-ctl-chip-item { display: inline-flex; align-items: center; gap: var(--space-2); min-height: 32px; padding: 0 var(--space-3); border: var(--control-border, 1px solid var(--color-border-strong, var(--color-border))); border-radius: var(--pill-radius, 999px); background: var(--control-bg, var(--color-surface)); color: var(--color-text); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); cursor: pointer; box-shadow: var(--control-shadow, none); }
.fl-ctl-chip-item.is-hover, .fl-ctl-chip-item:hover:not(:disabled) { background: var(--color-surface-sunken); }
.fl-ctl-chip-item.is-on { background: color-mix(in srgb, var(--color-accent) 14%, var(--color-surface)); border-color: var(--color-accent); color: var(--color-accent); font-weight: var(--weight-semibold); }
.fl-ctl-chip-item:disabled { opacity: 0.55; cursor: not-allowed; }
.fl-ctl-chip-item--label { cursor: default; }
.fl-ctl-chip-x { display: inline-grid; place-items: center; width: 1.25em; height: 1.25em; border: 0; border-radius: 50%; background: transparent; color: inherit; cursor: pointer; }
.fl-ctl-chip-x:hover:not(:disabled) { background: color-mix(in srgb, currentColor 18%, transparent); }
.fl-ctl-chip-x svg { width: 0.9em; height: 0.9em; }
.fl-ctl-chip-bar { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); }

/* ── Dropzone and the files under it ── */
.fl-ctl-zone-grid { display: grid; gap: var(--space-5); grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); margin: 0 0 var(--space-6); padding: 0; list-style: none; }
.fl-ctl-zone-grid > li { display: grid; gap: var(--space-1, 0.25rem); }
.fl-ctl-zone { display: grid; justify-items: center; gap: var(--space-2); margin-top: var(--space-2); padding: var(--space-6) var(--space-4); border: 2px dashed var(--color-border-strong, var(--color-border)); border-radius: min(var(--surface-radius, var(--radius-lg)), 12px); background: var(--surface-bg, var(--color-surface)); text-align: center; }
.fl-ctl-zone svg { width: 1.5rem; height: 1.5rem; color: var(--color-text-muted); }
.fl-ctl-zone.is-over { border-color: var(--color-accent); background: color-mix(in srgb, var(--color-accent) 8%, var(--color-surface)); }
.fl-ctl-zone.is-busy { border-style: solid; }
.fl-ctl-zone.is-error { border-color: var(--color-danger, #b42318); background: color-mix(in srgb, var(--color-danger, #b42318) 6%, var(--color-surface)); }
.fl-ctl-zone.is-error svg { color: var(--color-danger, #b42318); }
.fl-ctl-bar { display: block; width: 100%; max-width: 14rem; height: 6px; border-radius: var(--pill-radius, 999px); background: var(--color-surface-sunken); overflow: hidden; box-shadow: var(--well-shadow, none); }
.fl-ctl-bar > span { display: block; height: 100%; border-radius: inherit; background: var(--color-accent); }
.fl-ctl-file-list { display: grid; gap: var(--space-2); margin: 0; padding: 0; list-style: none; }
.fl-ctl-file-list li { display: flex; align-items: center; justify-content: space-between; gap: var(--space-4); padding: var(--space-3) var(--space-4); border: var(--surface-border, 1px solid var(--color-border)); border-radius: min(var(--surface-radius-sm, var(--radius-md)), 12px); }
.fl-ctl-file-list li.is-error { border-color: var(--color-danger, #b42318); }
.fl-ctl-file-main { display: grid; gap: var(--space-1, 0.25rem); min-width: 0; }
/* Three menus side by side, each one drawn open so it can be read here. */
.fl-ctl-menu-grid { display: grid; gap: var(--space-5); grid-template-columns: repeat(auto-fit, minmax(14rem, 1fr)); align-items: start; }
.fl-ctl-menu ul { margin: 0; padding: 0; list-style: none; }
.fl-ctl-menu-check { display: flex; align-items: center; gap: var(--space-2); width: 100%; padding: var(--space-2) var(--space-3); border-radius: var(--radius-sm); cursor: pointer; }
.fl-ctl-menu-check:hover { background: var(--color-surface-sunken); }
.fl-ctl-menu-foot { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); margin-top: var(--space-2); padding-top: var(--space-2); border-top: 1px solid var(--color-border); }
.fl-ctl-menu--actions li { gap: var(--space-3); cursor: pointer; }
.fl-ctl-menu--actions svg { width: 1rem; height: 1rem; flex: none; color: var(--color-text-muted); }
.fl-ctl-menu--actions li.is-danger { color: var(--color-danger, #b42318); margin-top: var(--space-2); padding-top: calc(var(--space-2) + var(--space-2)); border-top: 1px solid var(--color-border); border-radius: 0 0 var(--radius-sm) var(--radius-sm); }
.fl-ctl-menu--actions li.is-danger svg { color: inherit; }
.fl-ctl-menu--actions li.is-disabled { opacity: 0.5; cursor: not-allowed; }
.fl-ctl-menu-keys { margin-left: auto; padding: 0 var(--space-2); border: 1px solid var(--color-border); border-radius: var(--radius-sm); color: var(--color-text-muted); font-size: var(--text-xs, 0.78rem); font-family: var(--font-mono, ui-monospace, monospace); }
/* Chip heights: the lower half of the button scale, so a chip and a button line up in a filter bar. */
.fl-ctl-chip-item--20 { min-height: 20px; padding-inline: var(--space-2); font-size: var(--text-xs, 0.78rem); gap: var(--space-1, 0.25rem); }
.fl-ctl-chip-item--24 { min-height: 24px; padding-inline: var(--space-2); font-size: var(--text-xs, 0.78rem); }
.fl-ctl-chip-item--32 { min-height: 32px; }
.fl-ctl-chip-item--40 { min-height: 40px; padding-inline: var(--space-4); }
.fl-ctl-chip-item--44 { min-height: 44px; padding-inline: var(--space-4); font-size: max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))); }

/* ── Input specimens on a narrow screen ────────────────────────────────────── */
@container specimen (max-width: 760px) {
  .fl-ctl-chip-bar { gap: var(--space-2); }
  .fl-ctl-file-list li { flex-wrap: wrap; }
  .fl-ctl-setting-list li { flex-wrap: wrap; gap: var(--space-3); }
  .fl-ctl-slider--range { max-width: none; }
  .fl-ctl-menu { max-width: none; backdrop-filter: var(--surface-blur, none); -webkit-backdrop-filter: var(--surface-blur, none); }
}

/* A live filter chip: the label toggles, the x removes, and they are separate buttons. */
.fl-ctl-chip-face { border: 0; background: none; color: inherit; font: inherit; cursor: pointer; padding: 0; }
.fl-ctl-chip-item:has(.fl-ctl-chip-face) { padding-right: var(--space-2); }

/* ── The live dropzone, and a textarea that matches the fields ─────────────── */
.fl-ctl-zone--live { cursor: pointer; }
.fl-ctl-zone--live:hover { border-color: var(--color-secondary-border, var(--color-accent)); }
.fl-ctl-zone--live:focus-within { outline: none; box-shadow: var(--focus-ring); border-color: var(--color-accent); }
textarea.fl-ctl-field { min-height: 5rem; padding: var(--space-3); line-height: 1.5; resize: vertical; }

/* A message that is guidance rather than an error reads as guidance. */
.fl-ctl-field-msg.is-quiet { color: var(--color-text-muted); }

/* The live form: label, field, message, stacked, two across when there is room. */
