/* ── Choice group: swatches and pills (tiles reuse the radio cards above) ── */
.fl-ctl-cg { margin: 0; padding: 0; border: 0; min-width: 0; display: grid; gap: var(--space-2); }
.fl-ctl-cg > legend { padding: 0; margin-bottom: var(--space-2); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); font-weight: var(--weight-semibold); }
