.fl-ctl-cg__chip {
  display: inline-grid; place-items: center; min-width: var(--control-md); min-height: var(--control-sm); padding-inline: var(--space-3);
  border: 1px solid var(--color-border-strong); border-radius: var(--radius-md); background: var(--color-surface);
  font: var(--weight-semibold) max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))) / 1 var(--font-sans); color: var(--color-text);
  transition: background-color var(--duration-fast) var(--easing), border-color var(--duration-fast) var(--easing);
}
