.fl-ld-icon-btn { display: inline-grid; place-items: center; width: var(--control-md); height: var(--control-md); border-radius: var(--control-radius, var(--radius-md)); border: 1px solid var(--color-border-strong); background: var(--color-surface); color: var(--color-text); cursor: pointer; font: var(--weight-semibold) max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))) / 1 var(--font-sans); }
