/* ── Lead generation ── */
.fl-ld-lead-hero { padding: var(--space-8) var(--space-5) var(--space-9); }
.fl-ld-lead-grid { display: grid; grid-template-columns: minmax(0, 1.15fr) minmax(0, 0.85fr); gap: var(--space-8); align-items: center; }
