.fl-ld-formcard h2 { margin: 0; font: var(--weight-bold) max(11px, calc(var(--text-xl) - var(--fs-shrink, 0px))) / var(--leading-snug) var(--font-display); }
.fl-ld-trust { display: flex; flex-wrap: wrap; gap: var(--space-2) var(--space-5); margin: 0; padding: 0; list-style: none; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }
