.fl-ld-chapters { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-5) var(--space-7); margin: 0; padding: 0; list-style: none; counter-reset: fl-ld-ch; }
.fl-ld-chapters li { counter-increment: fl-ld-ch; display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--space-4); padding-top: var(--space-5); border-top: 1px solid var(--color-border); }
.fl-ld-chapters li::before { content: counter(fl-ld-ch, decimal-leading-zero); font: var(--weight-bold) max(11px, calc(var(--text-xl) - var(--fs-shrink, 0px))) / 1 var(--font-display); color: var(--color-secondary, var(--color-accent)); font-variant-numeric: tabular-nums; }
.fl-ld-chapters h3 { margin: 0 0 var(--space-2); font: var(--weight-semibold) max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))) / var(--leading-snug) var(--font-display); }
.fl-ld-cover { aspect-ratio: 3 / 4; max-width: 20rem; width: 100%; margin-inline: auto; border-radius: var(--radius-md) min(var(--radius-lg), 12px) min(var(--radius-lg), 12px) var(--radius-md); padding: var(--space-6); display: grid; align-content: space-between; color: var(--color-on-secondary, var(--color-on-accent)); background: linear-gradient(160deg, var(--color-secondary, var(--color-accent)), color-mix(in srgb, var(--color-secondary, var(--color-accent)) 55%, var(--color-text))); box-shadow: var(--surface-shadow-hover, none); border-left: 0.6rem solid color-mix(in srgb, var(--color-text) 25%, var(--color-secondary, var(--color-accent))); }
.fl-ld-cover strong { font: var(--weight-bold) max(11px, calc(var(--text-2xl) - var(--fs-shrink, 0px))) / var(--leading-tight) var(--font-display); }
.fl-ld-cover span { font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); opacity: 0.85; }

/* ── Long-form sales ── */
.fl-ld-sales-hero { text-align: center; display: grid; gap: var(--space-5); justify-items: center; }
.fl-ld-sales-hero .fl-lede { margin-inline: auto; }
.fl-ld-prose { display: grid; gap: var(--space-5); font-size: max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))); line-height: var(--leading-relaxed); }
