.fl-ld-pains { display: grid; gap: var(--space-4); margin: 0; padding: 0; list-style: none; }
.fl-ld-pains li { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--space-3); align-items: start; line-height: var(--leading-normal); }
.fl-ld-x { display: inline-grid; place-items: center; width: 1.25rem; height: 1.25rem; border-radius: 50%; background: var(--color-danger-surface); color: var(--color-danger); margin-top: 0.15rem; }
.fl-ld-x svg { width: 0.75rem; height: 0.75rem; }
.fl-ld-compare { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: var(--space-5); }
.fl-ld-compare .fl-card:first-child { background: var(--color-surface-sunken); }
.fl-ld-compare .fl-card:last-child { border-color: var(--color-accent); }
.fl-ld-modules { display: grid; gap: var(--space-3); margin: 0; padding: 0; list-style: none; }
.fl-ld-module { border: var(--surface-border, 1px solid var(--color-border)); border-radius: min(var(--radius-lg), 12px); background: var(--surface-bg, var(--color-surface)); overflow: hidden; box-shadow: var(--surface-shadow, none); backdrop-filter: var(--surface-blur, none); -webkit-backdrop-filter: var(--surface-blur, none); }
.fl-ld-module h3 { margin: 0; }
.fl-ld-module__btn { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: var(--space-4); align-items: center; width: 100%; padding: var(--space-4) var(--space-5); border: 0; background: transparent; color: var(--color-text); text-align: left; font: var(--weight-semibold) max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))) / var(--leading-snug) var(--font-sans); cursor: pointer; border-radius: min(var(--radius-lg), 12px); }
.fl-ld-module__week { font: var(--weight-semibold) max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))) / 1 var(--font-mono); color: var(--color-secondary, var(--color-accent)); letter-spacing: var(--tracking-wide); text-transform: uppercase; }
.fl-ld-module__chev { width: 1.1rem; height: 1.1rem; color: var(--color-text-muted); transition: transform var(--duration-fast) var(--easing); }
