.fl-ld-module__panel { padding: 0 var(--space-5) var(--space-5); color: var(--color-text-muted); line-height: var(--leading-relaxed); }
.fl-ld-module__panel ul { margin: var(--space-2) 0 0; padding-left: var(--space-5); display: grid; gap: var(--space-1); }
.fl-ld-pricecard { display: grid; gap: var(--space-5); justify-items: center; text-align: center; padding: var(--space-8) var(--space-6); border-radius: min(var(--radius-xl), 12px); background: var(--surface-bg, var(--color-surface)); color: var(--color-text); border: 2px solid var(--color-accent); box-shadow: var(--surface-shadow-hover, none); backdrop-filter: var(--surface-blur, none); -webkit-backdrop-filter: var(--surface-blur, none); }
.fl-ld-pricecard .fl-checks { text-align: left; justify-self: stretch; max-width: 26rem; margin-inline: auto; }
.fl-ld-bigprice { display: flex; align-items: baseline; justify-content: center; gap: var(--space-2); flex-wrap: wrap; }
.fl-ld-bigprice strong { font: var(--weight-bold) max(11px, calc(var(--text-3xl) - var(--fs-shrink, 0px))) / 1 var(--font-display); font-variant-numeric: tabular-nums; }
.fl-ld-bigprice s { color: var(--color-text-muted); }
.fl-ld-guarantee { display: grid; grid-template-columns: auto minmax(0, 1fr); gap: var(--space-6); align-items: center; }
.fl-ld-seal { width: 7rem; height: 7rem; color: var(--color-secondary, var(--color-accent)); }

/* ── Pre-launch ── */
.fl-ld-launch { min-height: 88vh; display: grid; grid-template-rows: auto 1fr auto; }
.fl-ld-launch__main { display: grid; align-content: center; justify-items: center; text-align: center; gap: var(--space-6); padding: var(--space-8) var(--space-5); }
.fl-ld-count { display: grid; grid-template-columns: repeat(4, minmax(0, 5.5rem)); gap: var(--space-3); margin: 0; justify-content: center; }
.fl-ld-count div { display: grid; gap: var(--space-2); justify-items: center; padding: var(--space-4) var(--space-2); border-radius: min(var(--radius-lg), 12px); background: color-mix(in srgb, var(--color-surface) 82%, transparent); border: 1px solid var(--color-border); box-shadow: var(--surface-shadow, none); }
.fl-ld-count dt { order: 2; font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); text-transform: uppercase; letter-spacing: var(--tracking-wide); color: var(--color-text-muted); }
.fl-ld-count dd { order: 1; margin: 0; font: var(--weight-bold) max(11px, calc(var(--text-2xl) - var(--fs-shrink, 0px))) / 1 var(--font-mono); font-variant-numeric: tabular-nums; }
