.fl-ld-joined { width: 100%; max-width: 30rem; display: grid; gap: var(--space-3); justify-items: center; padding: var(--space-6); border-radius: min(var(--radius-xl), 12px); background: var(--color-surface); border: 1px solid var(--color-border); box-shadow: var(--surface-shadow-hover, none); }
.fl-ld-joined__pos { font: var(--weight-bold) max(11px, calc(var(--text-3xl) - var(--fs-shrink, 0px))) / 1 var(--font-display); color: var(--color-accent); font-variant-numeric: tabular-nums; }
.fl-ld-refer { display: flex; gap: var(--space-2); width: 100%; }
.fl-ld-refer .fl-input { font-family: var(--font-mono); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-ld-pill { display: inline-flex; align-items: center; gap: var(--space-2); padding: var(--space-1) var(--space-3); border-radius: 999px; border: 1px solid var(--color-border); background: color-mix(in srgb, var(--color-surface) 80%, transparent); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }
.fl-ld-pill__dot { width: 0.5rem; height: 0.5rem; border-radius: 50%; background: var(--color-success); animation: fl-ld-pulse 2s var(--easing) infinite; }
@keyframes fl-ld-pulse { 50% { opacity: 0.35; } }
.fl-ld-teasers { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-6); }
.fl-ld-teasers > div { display: grid; gap: var(--space-2); }
.fl-ld-teasers h3 { margin: 0; font: var(--weight-semibold) max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))) / var(--leading-snug) var(--font-display); }

/* ── Product ── */
.fl-ld-product { display: grid; grid-template-columns: minmax(0, 1.1fr) minmax(0, 0.9fr); gap: var(--space-8); align-items: start; }
.fl-ld-gallery { display: grid; gap: var(--space-3); position: sticky; top: var(--space-5); }
.fl-ld-stage { aspect-ratio: 1; display: grid; place-items: center; border-radius: min(var(--radius-xl), 12px); border: 1px solid var(--color-border); color: var(--color-secondary, var(--color-accent)); background: radial-gradient(70% 60% at 50% 30%, color-mix(in srgb, var(--color-secondary, var(--color-accent)) 16%, transparent), transparent 70%), var(--color-surface-sunken); overflow: hidden; }
