.fl-ld-stage--room { background: linear-gradient(180deg, var(--color-surface-sunken) 0 68%, color-mix(in srgb, var(--color-text) 10%, var(--color-surface)) 68% 100%); }
.fl-ld-stage--night { background: radial-gradient(55% 45% at 50% 60%, color-mix(in srgb, var(--color-secondary, var(--color-accent)) 30%, transparent), transparent 70%), color-mix(in srgb, var(--color-text) 85%, var(--color-bg)); }
.fl-ld-thumbs { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--space-3); margin: 0; padding: 0; list-style: none; }
.fl-ld-thumb { width: 100%; aspect-ratio: 1; padding: var(--space-2); border-radius: var(--radius-md); border: 2px solid var(--color-border); background: var(--color-surface-sunken); color: var(--color-text-muted); cursor: pointer; font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); font-weight: var(--weight-semibold); transition: border-color var(--duration-fast) var(--easing); }
.fl-ld-thumb[aria-pressed="true"] { border-color: var(--color-accent); color: var(--color-text); }
.fl-ld-buy { display: grid; gap: var(--space-5); }
.fl-ld-rating { display: inline-flex; align-items: center; gap: var(--space-2); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }
.fl-ld-stars { display: inline-flex; gap: 0.1rem; color: var(--color-secondary, var(--color-accent)); }
.fl-ld-stars svg { width: 1rem; height: 1rem; }
.fl-ld-opts { border: 0; margin: 0; padding: 0; display: grid; gap: var(--space-3); min-width: 0; }
.fl-ld-opts legend { padding: 0; font-weight: var(--weight-semibold); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-ld-opts legend span { font-weight: var(--weight-regular); color: var(--color-text-muted); }
.fl-ld-optrow { display: flex; flex-wrap: wrap; gap: var(--space-3); }
.fl-ld-swatch { display: block; width: 2.5rem; height: 2.5rem; border-radius: 50%; border: 1px solid var(--color-border-strong); box-shadow: 0 0 0 3px var(--color-bg); cursor: pointer; }
.fl-ld-chip { display: inline-flex; align-items: center; min-height: var(--control-md); padding-inline: var(--space-4); border-radius: var(--control-radius, var(--radius-md)); border: 1px solid var(--color-border-strong); background: var(--color-surface); font-weight: var(--weight-medium); cursor: pointer; }
input:checked + .fl-ld-swatch { box-shadow: 0 0 0 3px var(--color-bg), 0 0 0 5px var(--color-accent); }
input:checked + .fl-ld-chip { border-color: var(--color-accent); background: color-mix(in srgb, var(--color-accent) 10%, var(--color-surface)); color: var(--color-text); box-shadow: inset 0 0 0 1px var(--color-accent); }
input:focus-visible + .fl-ld-swatch, input:focus-visible + .fl-ld-chip, input:focus-visible + .fl-ld-option { box-shadow: var(--focus-ring); }
.fl-ld-qty { display: inline-flex; align-items: center; gap: var(--space-2); }
.fl-ld-qty output { min-width: 2.5rem; text-align: center; font-weight: var(--weight-semibold); font-variant-numeric: tabular-nums; }
.fl-ld-buyrow { display: flex; gap: var(--space-4); align-items: center; flex-wrap: wrap; }
.fl-ld-buyrow .fl-btn { flex: 1 1 12rem; }
.fl-ld-bag { display: inline-flex; align-items: center; gap: var(--space-2); }
.fl-ld-bag__count { display: inline-grid; place-items: center; min-width: 1.4rem; height: 1.4rem; padding-inline: var(--space-1); border-radius: 999px; background: var(--color-secondary, var(--color-accent)); color: var(--color-on-secondary, var(--color-on-accent)); font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); font-weight: var(--weight-bold); }
.fl-ld-tabs { display: flex; gap: var(--space-5); border-bottom: 1px solid var(--color-border); overflow-x: auto; }
.fl-ld-tab { padding: var(--space-3) 0; border: 0; border-bottom: 2px solid transparent; margin-bottom: -1px; background: none; color: var(--color-text-muted); font: var(--weight-semibold) max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))) / 1 var(--font-sans); cursor: pointer; white-space: nowrap; }
.fl-ld-tab[aria-selected="true"] { color: var(--color-text); border-bottom-color: var(--color-accent); }
.fl-ld-tabpanel { padding-top: var(--space-5); color: var(--color-text-muted); line-height: var(--leading-relaxed); }
.fl-ld-specs { display: grid; grid-template-columns: minmax(0, 10rem) minmax(0, 1fr); margin: 0; }
.fl-ld-specs dt, .fl-ld-specs dd { margin: 0; padding: var(--space-3) 0; border-bottom: 1px solid var(--color-border); }
.fl-ld-specs dt { color: var(--color-text-muted); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-ld-specs dd { color: var(--color-text); }
.fl-ld-reviews { display: grid; grid-template-columns: minmax(0, 18rem) minmax(0, 1fr); gap: var(--space-8); align-items: start; }
.fl-ld-avg { font: var(--weight-bold) max(11px, calc(var(--text-3xl) - var(--fs-shrink, 0px))) / 1 var(--font-display); }
.fl-ld-dist { display: grid; gap: var(--space-2); margin: 0; padding: 0; list-style: none; }
.fl-ld-dist button { display: grid; grid-template-columns: 3.5rem minmax(0, 1fr) 2rem; gap: var(--space-3); align-items: center; width: 100%; padding: var(--space-1) var(--space-2); border: 1px solid transparent; border-radius: var(--radius-sm); background: none; color: var(--color-text-muted); font: inherit; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); cursor: pointer; text-align: left; }
.fl-ld-dist button:hover { background: var(--color-surface-sunken); }
.fl-ld-dist button[aria-pressed="true"] { border-color: var(--color-accent); color: var(--color-text); }
.fl-ld-meter { height: 0.5rem; border-radius: 999px; background: var(--color-surface-sunken); overflow: hidden; }
.fl-ld-meter span { display: block; height: 100%; border-radius: inherit; background: var(--color-accent); }
.fl-ld-review { display: grid; gap: var(--space-2); padding-block: var(--space-5); border-bottom: 1px solid var(--color-border); }
.fl-ld-review:first-child { padding-top: 0; }
.fl-ld-review h3 { margin: 0; font: var(--weight-semibold) max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))) / var(--leading-snug) var(--font-display); }

/* ── Subscription ── */
.fl-ld-builder { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 22rem); gap: var(--space-8); align-items: start; }
.fl-ld-steps { display: grid; gap: var(--space-7); }
.fl-ld-step-title { display: flex; align-items: center; gap: var(--space-3); margin: 0 0 var(--space-4); font: var(--weight-semibold) max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))) / var(--leading-snug) var(--font-display); }
.fl-ld-opts legend.fl-ld-step-title { font-size: max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))); font-weight: var(--weight-semibold); margin-bottom: var(--space-4); }
.fl-ld-step-num { display: inline-grid; place-items: center; width: 1.9rem; height: 1.9rem; border-radius: 50%; background: var(--color-secondary, var(--color-accent)); color: var(--color-on-secondary, var(--color-on-accent)); font: var(--weight-bold) max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))) / 1 var(--font-sans); flex: none; }
.fl-ld-options { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-3); }
.fl-ld-options--2 { grid-template-columns: repeat(2, minmax(0, 1fr)); }
.fl-ld-options > label { display: grid; }
.fl-ld-option { display: grid; gap: var(--space-1); align-content: start; padding: var(--space-5); border-radius: min(var(--radius-lg), 12px); border: 1px solid var(--color-border); background: var(--color-surface); cursor: pointer; transition: border-color var(--duration-fast) var(--easing); }
.fl-ld-option:hover { border-color: var(--color-border-strong); }
.fl-ld-option strong { font: var(--weight-semibold) max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))) / var(--leading-snug) var(--font-display); }
.fl-ld-option small { color: var(--color-text-muted); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-ld-option__price { font-weight: var(--weight-bold); font-variant-numeric: tabular-nums; }
input:checked + .fl-ld-option { border-color: var(--color-accent); box-shadow: inset 0 0 0 1px var(--color-accent); background: color-mix(in srgb, var(--color-accent) 7%, var(--color-surface)); }
.fl-ld-save { display: inline-flex; padding: 0.1rem var(--space-2); border-radius: 999px; background: color-mix(in srgb, var(--color-success) 14%, transparent); color: var(--color-success); font: var(--weight-semibold) max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))) / 1.5 var(--font-sans); }
.fl-ld-summary { position: sticky; top: var(--space-5); }
.fl-ld-lines { display: grid; gap: var(--space-3); margin: 0; }
.fl-ld-lines div { display: flex; justify-content: space-between; gap: var(--space-4); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-ld-lines dt { color: var(--color-text-muted); }
.fl-ld-lines dd { margin: 0; font-variant-numeric: tabular-nums; text-align: right; }
.fl-ld-lines .fl-ld-total { padding-top: var(--space-3); border-top: 1px solid var(--color-border); font-size: max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))); font-weight: var(--weight-bold); }
.fl-ld-lines .fl-ld-total dt { color: var(--color-text); }
.fl-ld-lines .fl-ld-discount dd { color: var(--color-success); }
.fl-ld-howto { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-6); margin: 0; padding: 0; list-style: none; }
.fl-ld-howto li { display: grid; gap: var(--space-2); }
.fl-ld-howto h3 { margin: 0; font: var(--weight-semibold) max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))) / var(--leading-snug) var(--font-display); }
.fl-ld-bags { display: flex; gap: var(--space-2); align-items: flex-end; height: 4rem; color: var(--color-secondary, var(--color-accent)); }
.fl-ld-bags svg { height: 100%; width: auto; }

/* ── Click-through ── */
.fl-ld-ct-hero { display: grid; justify-items: center; text-align: center; gap: var(--space-6); padding: var(--space-9) var(--space-5) var(--space-8); }
.fl-ld-ct-hero .fl-lede { margin-inline: auto; }
.fl-ld-proof { display: inline-flex; align-items: center; gap: var(--space-3); flex-wrap: wrap; justify-content: center; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }
.fl-ld-avatars { display: inline-flex; }
.fl-ld-avatars span { display: inline-grid; place-items: center; width: 2.25rem; height: 2.25rem; margin-left: -0.6rem; border-radius: 50%; border: 2px solid var(--color-bg); background: var(--color-secondary-surface, color-mix(in srgb, var(--color-accent) 20%, var(--color-surface))); color: var(--color-text); font: var(--weight-bold) max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))) / 1 var(--font-sans); }
.fl-ld-avatars span:first-child { margin-left: 0; }
.fl-ld-names { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--space-3) var(--space-7); margin: 0; padding: 0; list-style: none; font: var(--weight-bold) max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))) / 1 var(--font-display); color: var(--color-text-muted); opacity: 0.8; }
.fl-ld-calc { display: grid; grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--space-7); align-items: center; }
.fl-ld-range { width: 100%; accent-color: var(--color-accent); }
.fl-ld-result { display: grid; gap: var(--space-2); padding: var(--space-6); border-radius: min(var(--radius-xl), 12px); background: var(--color-secondary-surface, color-mix(in srgb, var(--color-accent) 10%, var(--color-surface))); border: 1px solid var(--color-secondary-border, color-mix(in srgb, var(--color-accent) 30%, transparent)); }
.fl-ld-result strong { font: var(--weight-bold) max(11px, calc(var(--text-3xl) - var(--fs-shrink, 0px))) / 1 var(--font-display); color: var(--color-accent); font-variant-numeric: tabular-nums; }
.fl-ld-carousel { display: grid; gap: var(--space-5); justify-items: center; text-align: center; }
.fl-ld-carousel__nav { display: flex; align-items: center; gap: var(--space-4); }
.fl-ld-dots { display: flex; gap: var(--space-2); margin: 0; padding: 0; list-style: none; }
.fl-ld-dots button { width: 0.6rem; height: 0.6rem; padding: 0; border-radius: 50%; border: 0; background: var(--color-border-strong); cursor: pointer; }
.fl-ld-dots button[aria-current="true"] { background: var(--color-accent); }
.fl-ld-final { display: grid; gap: var(--space-5); justify-items: center; text-align: center; max-width: 40rem; margin-inline: auto; }
.fl-ld-final .fl-inline-form { width: 100%; }
.fl-ld-final .fl-ld-error { color: var(--color-on-accent); font-weight: var(--weight-semibold); }
.fl-ld-final .fl-done { background: var(--color-on-accent); color: var(--color-accent); }

/* ── Motion ── */
@media (prefers-reduced-motion: reduce) {
  .fl-ld-module__chev, .fl-ld-thumb, .fl-ld-option { transition: none; }
  .fl-ld-pill__dot { animation: none; }
  .fl-ld-page { scroll-behavior: auto; }
}

/* ── Phones ── */
@media (max-width: 860px) {
  .fl-ld-lead-grid, .fl-ld-product, .fl-ld-builder, .fl-ld-reviews, .fl-ld-calc, .fl-ld-compare { grid-template-columns: minmax(0, 1fr); gap: var(--space-6); }
  .fl-ld-chapters, .fl-ld-teasers, .fl-ld-howto { grid-template-columns: minmax(0, 1fr); }
  .fl-ld-gallery, .fl-ld-summary { position: static; }
  .fl-ld-options { grid-template-columns: minmax(0, 1fr); }
  .fl-ld-guarantee { grid-template-columns: minmax(0, 1fr); justify-items: center; text-align: center; }
}
@media (max-width: 480px) {
  .fl-ld-count { grid-template-columns: repeat(4, minmax(0, 1fr)); gap: var(--space-2); }
  .fl-ld-count dd { font-size: max(11px, calc(var(--text-xl) - var(--fs-shrink, 0px))); }
  .fl-ld-count div { padding: var(--space-3) var(--space-1); }
  .fl-ld-options--2 { grid-template-columns: minmax(0, 1fr); }
  .fl-ld-specs { grid-template-columns: minmax(0, 1fr); }
  .fl-ld-specs dt { border-bottom: 0; padding-bottom: 0; }
  .fl-ld-refer { flex-direction: column; }
  .fl-ld-bar__aside .fl-ld-hide-sm { display: none; }
}

/* ── Product page: a garment ──────────────────────────────────────────────────
   The lamp page's gallery, swatches and buy row are reused as they are. What is new is everything the size decision
   needs: a size row that shows what is gone, a guide with the measurements, the fit note, and the fabric facts that
   belong beside the price rather than inside a tab. */
.fl-ld-price { display: flex; align-items: baseline; flex-wrap: wrap; gap: var(--space-3); margin: 0; }
.fl-ld-price strong { font: var(--weight-bold) max(11px, calc(var(--text-xl) - var(--fs-shrink, 0px))) / 1 var(--font-display); }
.fl-ld-price s { color: var(--color-text-muted); }
.fl-ld-sizehead { display: flex; align-items: baseline; justify-content: space-between; gap: var(--space-3); width: 100%; }
.fl-ld-guidelink { border: 0; background: none; padding: 0; color: var(--color-accent); font: inherit; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); text-decoration: underline; cursor: pointer; }
.fl-ld-sizes { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.fl-ld-size { position: relative; display: grid; place-items: center; min-width: 3.25rem; min-height: var(--control-lg); padding-inline: var(--space-3); border: 1px solid var(--color-border-strong); border-radius: var(--control-radius, var(--radius-sm)); background: var(--color-surface); font-weight: var(--weight-semibold); cursor: pointer; }
.fl-ld-size:has(input:checked) { border-color: var(--color-accent); box-shadow: inset 0 0 0 1px var(--color-accent); }
.fl-ld-size:has(input:focus-visible) { box-shadow: var(--focus-ring); }
/* Sold out is struck through, not merely greyed: colour alone would not say it, and the size stays pressable so the
   page can offer to tell you when it is back. */
.fl-ld-size.is-gone { color: var(--color-text-muted); border-style: dashed; }
.fl-ld-size.is-gone > span:first-of-type { text-decoration: line-through; }
.fl-ld-notify { display: grid; gap: var(--space-2); }
.fl-ld-status { min-height: 1.5em; margin: 0; color: var(--color-text-muted); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-ld-fit { display: grid; gap: var(--space-3); padding-top: var(--space-4); border-top: 1px solid var(--color-border); }
.fl-ld-fit p { margin: 0; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); line-height: var(--leading-relaxed); }
.fl-ld-fit .fl-ld-fine svg { width: 1rem; height: 1rem; vertical-align: -0.2em; }
.fl-ld-fabric { display: grid; gap: var(--space-2); margin: 0; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-ld-fabric > div { display: grid; grid-template-columns: minmax(5rem, 7rem) minmax(0, 1fr); gap: var(--space-3); }
.fl-ld-fabric dt { color: var(--color-text-muted); }
.fl-ld-fabric dd { margin: 0; }
/* The size guide: a dialog, because the measurements are a detour from buying and have to be dismissable. */
.fl-ld-guide-scrim { position: absolute; inset: 0; z-index: 60; display: grid; place-items: center; padding: var(--space-4); background: color-mix(in srgb, var(--color-text) 45%, transparent); }
.fl-ld-guide { display: grid; gap: var(--space-3); width: min(34rem, 100%); max-height: 100%; overflow: auto; border-radius: min(var(--radius-lg), 12px); background: var(--surface-bg, var(--color-surface)); padding: var(--space-5); box-shadow: var(--surface-shadow, none); backdrop-filter: var(--surface-blur, none); -webkit-backdrop-filter: var(--surface-blur, none); }
.fl-ld-guide-head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-4); }
.fl-ld-guide-head .fl-title { margin: 0; font-size: max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))); }
.fl-ld-guide-wrap { overflow-x: auto; }
.fl-ld-guide-table { width: 100%; border-collapse: collapse; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-ld-guide-table th, .fl-ld-guide-table td { padding: var(--space-2) var(--space-3); text-align: right; border-bottom: 1px solid var(--color-border); font-variant-numeric: tabular-nums; }
.fl-ld-guide-table th:first-child, .fl-ld-guide-table thead th:first-child { text-align: left; }
.fl-ld-guide-table thead th { color: var(--color-text-muted); font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); text-transform: uppercase; letter-spacing: 0.05em; }
.fl-ld-guide-table tbody tr.is-on { background: color-mix(in srgb, var(--color-accent) 12%, transparent); }
/* A c.choice-group under a numbered step title: the group's own legend stays for screen readers only. */
.fl-ctl-cg.fl-ld-cg > legend { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; border: 0; }


/* ── Marketplace browse page (t.app-marketplace) ── */
.fl-mkt-app {
  container: fl-mkt / inline-size;
  position: relative; display: flex; flex-direction: column; min-height: 40rem; overflow: hidden;
  border: 1px solid var(--color-border); border-radius: min(var(--surface-radius, var(--radius-lg)), 12px);
  background: var(--color-bg); color: var(--color-text); font-family: var(--font-sans); font-size: max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))); line-height: var(--leading-normal);
}
.fl-mkt-app :is(a, button, input, select, textarea, summary, [tabindex]):focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-mkt-app :where(h1, h2, h3, p) { margin: 0; }
.fl-mkt-app :where(button) { font: inherit; }

/* Top bar */
.fl-mkt-top {
  display: flex; align-items: center; gap: var(--space-5); padding: var(--space-3) var(--space-5);
  background: var(--header-bg, var(--color-surface)); border-bottom: 1px solid var(--color-border);
}
.fl-mkt-brand { display: flex; align-items: center; gap: var(--space-3); flex: none; color: var(--color-text); text-decoration: none; border-radius: var(--radius-sm); }
.fl-mkt-mark {
  display: inline-grid; place-items: center; width: 2.25rem; height: 2.25rem; border-radius: var(--radius-md);
  background: var(--color-accent); color: var(--color-on-accent); font: var(--weight-bold) max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))) / 1 var(--font-display);
}
.fl-mkt-brand__name { font: var(--weight-bold) max(11px, calc(var(--text-lg) - var(--fs-shrink, 0px))) / 1.2 var(--font-display); letter-spacing: var(--tracking-tight); white-space: nowrap; }
.fl-mkt-top__end { display: flex; align-items: center; gap: var(--space-2); flex: none; margin-left: auto; }

/* Search: what and where, then go */
.fl-mkt-search { flex: 1; display: flex; align-items: center; gap: var(--space-2); min-width: 0; max-width: 46rem; }
.fl-mkt-search__field { position: relative; display: block; min-width: 0; }
.fl-mkt-search__field--q { flex: 2; }
.fl-mkt-search__field--loc { flex: 1; min-width: 9rem; }
.fl-mkt-search__field > svg { position: absolute; left: var(--space-3); top: 50%; width: 1.125rem; height: 1.125rem; transform: translateY(-50%); color: var(--color-text-muted); pointer-events: none; z-index: 1; }
.fl-mkt-search .fl-input { width: 100%; padding-left: calc(var(--space-3) + 1.75rem); }
.fl-mkt-search__go { flex: none; }

/* Category chips */
.fl-mkt-cats { display: flex; gap: var(--space-2); padding: var(--space-3) var(--space-5); overflow-x: auto; border-bottom: 1px solid var(--color-border); scrollbar-width: thin; }
.fl-mkt-cats .fl-ctl-chip-item { flex: none; white-space: nowrap; }
.fl-mkt-cats__n { font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); font-variant-numeric: tabular-nums; color: var(--color-text-muted); }
.fl-mkt-cats .is-on .fl-mkt-cats__n { color: inherit; }

/* Body: filters beside results */
.fl-mkt-body { flex: 1; display: grid; grid-template-columns: 16.5rem minmax(0, 1fr); align-items: start; min-height: 0; }

.fl-mkt-filters { display: grid; gap: var(--space-4); padding: var(--space-5); border-right: 1px solid var(--color-border); align-self: stretch; }
.fl-mkt-filters__head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-2); }
.fl-mkt-filters__n { color: var(--color-text-muted); font-weight: var(--weight-medium); }
.fl-mkt-filters__toggle { display: none; }
.fl-mkt-filters__body { display: grid; gap: var(--space-5); }
.fl-mkt-group { display: grid; gap: var(--space-2); min-width: 0; margin: 0; padding: 0 0 var(--space-5); border: 0; border-bottom: 1px solid var(--color-border); }
.fl-mkt-group:last-child { padding-bottom: 0; border-bottom: 0; }
.fl-mkt-legend { padding: 0; margin-bottom: var(--space-2); font: var(--weight-semibold) max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))) / 1.3 var(--font-sans); }
.fl-mkt-filters .fl-ctl-slider--range { max-width: none; }
.fl-mkt-filters .fl-in-minmax { grid-template-columns: minmax(0, 1fr) minmax(0, 1fr); gap: var(--space-2); }
.fl-mkt-filters .fl-in-minmax__dash { display: none; }
.fl-mkt-filters .fl-in-minmax .fl-input { width: 100%; min-width: 0; }
