  border: 0; border-radius: min(var(--control-radius, var(--radius-md)), 12px); background: var(--color-accent); color: var(--color-on-accent);
  box-shadow: var(--surface-shadow-hover, var(--surface-shadow, none)); font-weight: var(--weight-semibold); text-align: left; cursor: pointer;
