/* Confirmation */
.fl-mord-done { justify-items: center; gap: var(--space-2); text-align: center; }
.fl-mord-done__check {
  display: grid; place-items: center; width: 3.5rem; height: 3.5rem; border-radius: var(--pill-radius, 999px);
  background: color-mix(in srgb, var(--color-success) 16%, var(--color-bg)); color: var(--color-success);
