.fl-ntf-bell:hover { background: var(--color-surface-sunken); }
.fl-ntf-bell:active { scale: 0.95; }
.fl-ntf-bell:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-ntf-bell[aria-expanded="true"] { background: var(--color-surface-sunken); }
