  display: grid; grid-template-rows: auto auto minmax(0, 1fr) auto; max-height: min(34rem, calc(100dvh - 6rem));
  background: var(--color-surface); color: var(--color-text); border: 1px solid var(--color-border);
  border-radius: min(var(--surface-radius, var(--radius-lg)), 12px); box-shadow: var(--shadow-lg, var(--shadow-md, none));
  transform-origin: top right; opacity: 1; scale: 1; translate: 0 0;
  transition: opacity var(--duration-base) var(--ease-out, var(--easing)), scale var(--duration-base) var(--ease-out, var(--easing)), translate var(--duration-base) var(--ease-out, var(--easing));
}
