.fl-ntf--start .fl-ntf-panel { left: 0; transform-origin: top left; }

.fl-ntf-head { display: flex; align-items: center; justify-content: space-between; gap: var(--space-3); padding: var(--space-4) var(--space-4) var(--space-2); }
.fl-ntf-head h3 { margin: 0; font-family: var(--font-display); font-size: max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))); font-weight: var(--weight-semibold); }
.fl-ntf-head h3:focus { outline: none; }
.fl-ntf-head h3:focus-visible { box-shadow: var(--focus-ring); border-radius: 4px; }
.fl-ntf-link {
  padding: var(--space-1) var(--space-2); border: 0; border-radius: var(--radius-sm, 4px); background: none; color: var(--color-accent);
  font: var(--weight-medium) max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))) / 1.2 var(--font-sans); text-decoration: none; cursor: pointer;
}
