.fl-ntf-tab {
  display: inline-flex; align-items: center; gap: var(--space-2); min-height: 2.5rem; padding: 0 var(--space-2);
  border: 0; background: none; color: var(--color-text-muted); font: var(--weight-medium) max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))) / 1 var(--font-sans); cursor: pointer;
  transition: color var(--duration-fast) var(--ease-out, var(--easing));
