.fl-social-list { display: grid; border: var(--surface-border, 1px solid var(--color-border)); border-radius: min(var(--surface-radius, var(--radius-lg)), 12px); overflow: hidden; background: var(--surface-bg, var(--color-surface)); box-shadow: var(--surface-shadow, none); }
.fl-social-list > li + li { border-top: 1px solid var(--color-border); }
