/* ── Right column ── */
.fl-social-rail { display: grid; align-content: start; gap: var(--space-4); padding: var(--space-5) var(--space-4); min-width: 0; }
.fl-social-card { display: grid; gap: var(--space-3); padding: var(--space-4); min-width: 0; }
.fl-social-topics { display: grid; gap: var(--space-1); margin-inline: calc(var(--space-2) * -1); }
.fl-social-topic {
  display: grid; gap: 2px; width: 100%; padding: var(--space-2); border: 0; border-radius: var(--radius-md);
  background: transparent; cursor: pointer; text-align: left;
  transition: background-color var(--duration-fast) var(--easing);
