.fl-social-topic .fl-social-meta { font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); }
.fl-social-topic strong { font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); overflow-wrap: anywhere; }
.fl-social-topic:hover { background: var(--color-surface-sunken); }
