/* ── Narrower frames: the right column moves below the feed, the rail keeps only its icons ── */
@container fl-social (max-width: 1080px) {
  .fl-social-layout { grid-template-columns: 4.5rem minmax(0, 1fr); }
  .fl-social-side { grid-row: span 2; padding-inline: var(--space-3); align-items: center; }
  .fl-social-brand { padding: 0; }
