  .fl-social-nav__item { justify-content: center; padding: 0; width: var(--control-md); }
  .fl-social-count { position: absolute; top: 2px; right: 0; min-width: 1.1rem; padding: 0 4px; line-height: 1.1rem; margin: 0; }
  .fl-social-me { padding-inline: 0; }
  .fl-social-main { border-right: 0; min-height: 0; }
  .fl-social-rail { grid-column: 2; grid-template-columns: repeat(2, minmax(0, 1fr)); align-items: start; padding-top: 0; padding-inline: var(--space-5); padding-bottom: var(--space-5); }
}

/* ── Phones: one column, the rail becomes a row of icons at the top ── */
@container fl-social (max-width: 640px) {
  .fl-social-layout { grid-template-columns: minmax(0, 1fr); }
  .fl-social-side {
    grid-row: auto; flex-direction: row; align-items: center; justify-content: space-between; gap: var(--space-2); min-height: 0;
    padding: var(--space-2) var(--space-3); border-right: 0; border-bottom: 1px solid var(--color-border);
  }
  .fl-social-side nav { flex: 1; }
  .fl-social-nav { display: flex; justify-content: space-around; gap: 0; }
  .fl-social-me { display: none; }
  .fl-social-main { padding: var(--space-4) var(--space-3); }
  .fl-social-rail { grid-column: 1; grid-template-columns: minmax(0, 1fr); padding: 0 var(--space-3) var(--space-4); }
  .fl-social-composer, .fl-social-post { padding: var(--space-3); }
  .fl-social-act { min-width: 0; }
  .fl-social-actions { justify-content: space-between; margin-left: 0; }
  .fl-social-profile { flex-direction: column; }
}
@container fl-social (max-width: 380px) {
  .fl-social-brand { display: none; }
  .fl-social-post { grid-template-columns: minmax(0, 1fr); }
  .fl-social-post > .fl-ctl-avatar { display: none; }
  .fl-social-replyform { flex-direction: column; }
}

/* ── Less motion ── */
@media (prefers-reduced-motion: reduce) {
  .fl-social-app *, .fl-social-app *::before, .fl-social-app *::after { transition: none !important; animation: none !important; }
  .fl-social-act:active svg { transform: none; }
