.fl-sdm-convs { flex: 1; min-height: 0; overflow-y: auto; padding: 0 var(--space-2) var(--space-3); }
.fl-sdm-conv {
  display: flex; align-items: center; gap: var(--space-3); width: 100%; padding: var(--space-3) var(--space-2);
  border: 0; border-radius: var(--radius-md); background: transparent; cursor: pointer; text-align: left;
  transition: background-color var(--duration-fast) var(--easing);
}
.fl-sdm-conv:hover { background: var(--color-surface-sunken); }
.fl-sdm-conv[aria-current="true"] { background: color-mix(in srgb, var(--color-accent) 12%, transparent); }
.fl-sdm-face { position: relative; display: inline-flex; flex: none; }
.fl-sdm-presence {
  position: absolute; right: 0; bottom: 0; width: 0.75rem; height: 0.75rem; border-radius: 999px;
  background: var(--color-success); box-shadow: 0 0 0 2px var(--surface-bg, var(--color-surface));
}
.fl-sdm-conv__body { display: grid; gap: 2px; flex: 1; min-width: 0; }
.fl-sdm-conv__top { display: flex; align-items: center; gap: var(--space-1); min-width: 0; }
.fl-sdm-conv__top strong { font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); font-weight: var(--weight-medium); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fl-sdm-conv__time { margin-left: auto; padding-left: var(--space-2); flex: none; color: var(--color-text-muted); font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); font-variant-numeric: tabular-nums; }
.fl-sdm-conv__last { color: var(--color-text-muted); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fl-sdm-conv[data-unread] .fl-sdm-conv__top strong { font-weight: var(--weight-bold); }
.fl-sdm-conv[data-unread]:not([data-muted]) .fl-sdm-conv__last { color: var(--color-text); }
.fl-sdm-conv[data-unread]:not([data-muted]) .fl-sdm-conv__time { color: var(--color-accent); font-weight: var(--weight-semibold); }
.fl-sdm-flag { display: inline-flex; flex: none; color: var(--color-text-muted); }
.fl-sdm-flag svg { width: 0.875rem; height: 0.875rem; }
.fl-sdm-unread { flex: none; width: 0.625rem; height: 0.625rem; border-radius: 999px; background: var(--color-accent); }
.fl-sdm-conv[data-muted] .fl-sdm-unread { background: var(--color-text-muted); }

/* ── Open thread ── */
.fl-sdm-thread { display: grid; grid-template-rows: auto minmax(0, 1fr) auto; min-width: 0; min-height: 0; }
.fl-sdm-thread__head {
  display: flex; align-items: center; gap: var(--space-3); min-width: 0; padding: var(--space-3) var(--space-5);
  border-bottom: 1px solid var(--color-border); background: var(--surface-bg, var(--color-surface));
}
.fl-sdm-back { display: none; margin-left: calc(var(--space-2) * -1); }
.fl-sdm-who { display: grid; flex: 1; min-width: 0; }
.fl-sdm-who .fl-sdm-meta { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.fl-sdm-who .fl-sdm-meta[data-online] { color: var(--color-success); }
.fl-sdm-tools { display: flex; gap: var(--space-1); flex: none; }
.fl-sdm-tool {
  display: inline-grid; place-items: center; width: var(--control-sm); height: var(--control-sm); padding: 0;
  border: 0; border-radius: var(--radius-md); background: transparent; color: var(--color-text-muted); cursor: pointer;
  transition: background-color var(--duration-fast) var(--easing), color var(--duration-fast) var(--easing);
}
.fl-sdm-tool svg { width: 1.125rem; height: 1.125rem; }
.fl-sdm-tool:hover { background: var(--color-surface-sunken); color: var(--color-text); }
.fl-sdm-tool[aria-pressed="true"] { background: color-mix(in srgb, var(--color-accent) 12%, transparent); color: var(--color-accent); }

/* Messages, by day and by sender */
.fl-sdm-scroll { min-height: 0; overflow-x: hidden; overflow-y: auto; padding: var(--space-4) var(--space-5); overscroll-behavior: contain; }
.fl-sdm-log { display: grid; gap: var(--space-5); }
.fl-sdm-day { display: grid; gap: var(--space-4); }
.fl-sdm-day__label {
  display: flex; align-items: center; gap: var(--space-3); color: var(--color-text-muted);
  font: var(--weight-semibold) max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))) / 1 var(--font-sans); letter-spacing: var(--tracking-wide, 0.04em); text-transform: uppercase;
}
.fl-sdm-day__label::before, .fl-sdm-day__label::after { content: ""; flex: 1; height: 1px; background: var(--color-border); }
.fl-sdm-run { display: flex; align-items: flex-end; gap: var(--space-2); min-width: 0; max-width: min(34rem, 88%); }
.fl-sdm-run[data-mine] { margin-left: auto; justify-content: flex-end; }
.fl-sdm-run__face { flex: none; margin-bottom: 1.25rem; }
.fl-sdm-run__msgs { display: flex; flex-direction: column; align-items: flex-start; gap: 3px; min-width: 0; }
.fl-sdm-run[data-mine] .fl-sdm-run__msgs { align-items: flex-end; }
.fl-sdm-msg { display: flex; flex-direction: column; align-items: inherit; gap: var(--space-2); max-width: 100%; min-width: 0; }
.fl-sdm-bubble {
  max-width: 100%; padding: var(--space-2) var(--space-3); overflow-wrap: anywhere; white-space: pre-wrap;
  border-radius: min(var(--radius-lg), 12px); background: var(--color-surface-sunken); color: var(--color-text); line-height: var(--leading-snug);
}
.fl-sdm-run:not([data-mine]) .fl-sdm-msg:not(:first-of-type) .fl-sdm-bubble { border-top-left-radius: 4px; }
.fl-sdm-run:not([data-mine]) .fl-sdm-msg:not(:last-of-type) .fl-sdm-bubble { border-bottom-left-radius: 4px; }
.fl-sdm-run[data-mine] .fl-sdm-bubble { background: var(--color-accent); color: var(--color-on-accent); }
.fl-sdm-run[data-mine] .fl-sdm-msg:not(:first-of-type) .fl-sdm-bubble { border-top-right-radius: 4px; }
.fl-sdm-run[data-mine] .fl-sdm-msg:not(:last-of-type) .fl-sdm-bubble { border-bottom-right-radius: 4px; }
.fl-sdm-msg[data-fresh] { animation: fl-sdm-in var(--duration-base) var(--easing); }
@keyframes fl-sdm-in { from { opacity: 0; transform: translateY(6px); } to { opacity: 1; transform: none; } }
.fl-sdm-run__time { display: inline-flex; flex-wrap: wrap; align-items: center; gap: 0; margin-top: 2px; color: var(--color-text-muted); font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); font-variant-numeric: tabular-nums; }
.fl-sdm-receipt { display: inline-flex; align-items: center; gap: 2px; white-space: pre; }
.fl-sdm-receipt svg { width: 0.875rem; height: 0.875rem; }
.fl-sdm-receipt[data-status="read"] { color: var(--color-accent); }

/* A shared link */
.fl-sdm-link {
  display: flex; gap: var(--space-3); width: 22rem; max-width: 100%; padding: var(--space-3); overflow: hidden;
  background: var(--surface-bg, var(--color-surface)); border: var(--surface-border, 1px solid var(--color-border));
  border-radius: min(var(--surface-radius, var(--radius-lg)), 12px); box-shadow: var(--surface-shadow, none);
}
.fl-sdm-link__thumb { flex: none; width: 4rem; height: 4rem; border-radius: var(--radius-md); }
.fl-sdm-link__ground { fill: color-mix(in srgb, var(--color-accent) 10%, var(--color-surface)); }
.fl-sdm-link__street { stroke: color-mix(in srgb, var(--color-text) 18%, var(--color-surface)); stroke-width: 5; fill: none; }
.fl-sdm-link__route { stroke: var(--color-accent); stroke-width: 3; fill: none; stroke-linecap: round; stroke-linejoin: round; }
.fl-sdm-link__dot { fill: var(--color-danger); }
.fl-sdm-link__body { display: grid; gap: 2px; min-width: 0; align-content: start; }
.fl-sdm-link__body strong { font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); line-height: var(--leading-snug); }
.fl-sdm-link__domain { color: var(--color-text-muted); font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); }
.fl-sdm-link__text { color: var(--color-text-muted); font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); line-height: var(--leading-snug); }

/* The shared photo, drawn in the theme's colors */
.fl-sdm-photo { width: 18rem; max-width: 100%; aspect-ratio: 8 / 5; overflow: hidden; border: 1px solid var(--color-border); border-radius: min(var(--radius-lg), 12px); background: var(--color-surface-sunken); }
.fl-sdm-photo svg { display: block; width: 100%; height: 100%; }
.fl-sdm-photo__paper { fill: color-mix(in srgb, var(--color-warning) 10%, var(--color-surface)); }
.fl-sdm-photo__block { fill: color-mix(in srgb, var(--color-secondary, var(--color-accent)) 26%, var(--color-surface)); }
.fl-sdm-photo__walk { fill: color-mix(in srgb, var(--color-text) 10%, var(--color-surface)); }
.fl-sdm-photo__lane { fill: color-mix(in srgb, var(--color-success) 55%, var(--color-surface)); }
.fl-sdm-photo__curb { fill: color-mix(in srgb, var(--color-text) 40%, var(--color-surface)); }
.fl-sdm-photo__road { fill: color-mix(in srgb, var(--color-text) 62%, var(--color-surface)); }
.fl-sdm-photo__dash { stroke: color-mix(in srgb, var(--color-warning) 80%, var(--color-surface)); stroke-width: 3; fill: none; }
.fl-sdm-photo__car { fill: color-mix(in srgb, var(--color-accent) 70%, var(--color-surface)); }
.fl-sdm-photo__bike { fill: none; stroke: var(--color-text); stroke-width: 2.5; stroke-linecap: round; stroke-linejoin: round; }
.fl-sdm-photo__tree { fill: color-mix(in srgb, var(--color-success) 80%, var(--color-text)); }

/* Composer */
.fl-sdm-composer {
  display: grid; grid-template-columns: minmax(0, 1fr) auto; align-items: end; gap: var(--space-2) var(--space-2);
  padding: var(--space-3) var(--space-5) var(--space-3); border-top: 1px solid var(--color-border); background: var(--surface-bg, var(--color-surface));
}
.fl-sdm-composer textarea.fl-input { min-height: var(--control-md); padding-block: var(--space-2); max-height: 8rem; resize: none; font-size: max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))); overflow-y: auto; }
.fl-sdm-keys { grid-column: 1 / -1; color: var(--color-text-muted); font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); }

/* Another section of the rail */
.fl-sdm-elsewhere { grid-column: 2 / -1; display: grid; place-items: start center; padding: var(--space-7) var(--space-5); min-width: 0; }
.fl-sdm-elsewhere__card {
  display: grid; justify-items: start; gap: var(--space-3); width: 100%; max-width: 32rem; padding: var(--space-5);
  background: var(--surface-bg, var(--color-surface)); border: var(--surface-border, 1px solid var(--color-border));
  border-radius: min(var(--surface-radius, var(--radius-lg)), 12px); box-shadow: var(--surface-shadow, none);
}

/* ── Narrower frames: the rail keeps only its icons ── */
@container fl-sdm (max-width: 1100px) {
  .fl-sdm-layout { grid-template-columns: 4.5rem 18rem minmax(0, 1fr); }
  .fl-sdm-side { padding-inline: var(--space-3); align-items: center; }
  .fl-sdm-brand { padding: 0; }
  .fl-sdm-brand__name, .fl-sdm-nav__label, .fl-sdm-me > span:last-child { position: absolute; width: 1px; height: 1px; overflow: hidden; clip: rect(0 0 0 0); white-space: nowrap; }
  .fl-sdm-nav__item { justify-content: center; padding: 0; width: var(--control-md); }
  .fl-sdm-count { position: absolute; top: 2px; right: 0; min-width: 1.1rem; padding: 0 4px; line-height: 1.1rem; margin: 0; }
  .fl-sdm-me { padding-inline: 0; }
  .fl-sdm-run { max-width: 92%; }
}

/* ── Phones: the rail becomes a row of icons, then the list or the open thread ── */
@container fl-sdm (max-width: 720px) {
  .fl-sdm-layout { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); height: 40rem; }
  .fl-sdm-side {
    flex-direction: row; align-items: center; justify-content: space-between; gap: var(--space-2);
    padding: var(--space-2) var(--space-3); border-right: 0; border-bottom: 1px solid var(--color-border);
  }
  .fl-sdm-side nav { flex: 1; }
  .fl-sdm-nav { display: flex; justify-content: space-around; gap: 0; }
  .fl-sdm-me { display: none; }
  .fl-sdm-list { border-right: 0; }
  .fl-sdm-layout[data-pane="thread"] .fl-sdm-list, .fl-sdm-layout[data-pane="list"] .fl-sdm-thread { display: none; }
  .fl-sdm-back { display: inline-flex; }
  .fl-sdm-thread__head { padding: var(--space-2) var(--space-3); gap: var(--space-2); }
  .fl-sdm-scroll { padding: var(--space-3); }
  .fl-sdm-composer { padding: var(--space-2) var(--space-3); }
  .fl-sdm-list__head { padding: var(--space-4) var(--space-3) var(--space-3); }
  .fl-sdm-elsewhere { grid-column: 1; padding: var(--space-5) var(--space-3); }
}
@container fl-sdm (max-width: 400px) {
  .fl-sdm-brand { display: none; }
  .fl-sdm-run { max-width: 100%; }
  .fl-sdm-run__face { display: none; }
  .fl-sdm-keys { display: none; }
  .fl-sdm-link { flex-direction: column; }
}

/* ── Less motion ── */
@media (prefers-reduced-motion: reduce) {
  .fl-sdm-app *, .fl-sdm-app *::before, .fl-sdm-app *::after { transition: none !important; animation: none !important; }
}


/**
 * Styles for the component specimens: the pieces that show one family of control in every variant and state.
 * Everything here is prefixed fl-ctl-, like controls.css and inputs.css, and uses only the library's own tokens.
 */

/* ── Reference sheet layout ─────────────────────────────────────────────────
   A sheet is a grid of topic cards (fl-ctl-spec): each holds one heading, one line on what it shows, and the working
   examples. Cards sit side by side when there is room, so a sheet is a screen or two, not a long scroll. A card that
   needs the full width (a state matrix, a toolbar, a live demo) adds fl-ctl-spec--wide. A topic whose examples are
   themselves cards or panels uses fl-ctl-spec--bare: same place in the grid, no frame, so no card sits inside a card. */
.fl-section--specimen:has(> .fl-ctl-spec) {
  display: grid; grid-template-columns: repeat(auto-fill, minmax(min(100%, 22rem), 1fr)); grid-auto-flow: row dense; gap: var(--space-4); align-items: start;
}
.fl-ctl-spec {
  display: grid; gap: var(--space-2); align-content: start; min-width: 0; margin: 0; padding: var(--space-4) var(--space-5);
  border: var(--surface-border, 1px solid var(--color-border)); border-radius: min(var(--radius-lg), 12px); background: var(--surface-bg, var(--color-surface)); box-shadow: var(--surface-shadow, none); backdrop-filter: var(--surface-blur, none); -webkit-backdrop-filter: var(--surface-blur, none); }
.fl-ctl-spec--wide { grid-column: 1 / -1; }
.fl-ctl-spec--bare { padding: 0; border: 0; background: none; }
.fl-ctl-spec > h3 { margin: 0; font-size: max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))); line-height: var(--leading-snug); }
.fl-ctl-spec > .fl-ctl-btn-what { margin: 0 0 var(--space-2); }
/* Inside a card the examples keep to themselves: no extra air above or below their lists and bars. */
.fl-ctl-spec > :is(ul, ol, div, table):not(:first-child) { margin-top: 0; margin-bottom: 0; }
.fl-ctl-spec.fl-ctl-sizes { margin-top: 0; }
/* Labels in a sheet are lines, not paragraphs: their default margins doubled the height of every example. */
.fl-section--specimen :is(p.fl-ctl-matrix-kind, p.fl-ctl-matrix-what) { margin: 0; }
.fl-section--specimen p.fl-ctl-matrix-kind { font-weight: var(--weight-semibold); }

/* ── Vertical tabs ──────────────────────────────────────────────────────────── */
.fl-ctl-vtabs-list { display: grid; gap: var(--space-6); margin: 0 0 var(--space-6); padding: 0; list-style: none; }
.fl-ctl-vtabs-list > li { display: grid; gap: var(--space-1, 0.25rem); min-width: 0; }
.fl-ctl-vtabs { display: grid; grid-template-columns: minmax(10rem, 15rem) minmax(0, 1fr); gap: var(--space-5); margin-top: var(--space-3); }
.fl-ctl-vtabs-rail { display: grid; align-content: start; gap: var(--space-1, 0.25rem); border-left: 2px solid var(--color-border); padding-left: var(--space-2); }
.fl-ctl-vtabs--filled .fl-ctl-vtabs-rail { border-left: 0; padding-left: 0; }
/* Square: a rail is a run of rows against an edge, and a corner on each row fights the line that marks the one you
   are on. The count keeps its pill, because that is a badge rather than a row. */
.fl-ctl-vtab {
  display: flex; align-items: center; gap: var(--space-2); width: 100%;
  border: 0; border-radius: 0; background: none; padding: var(--space-2) var(--space-3);
  color: var(--color-text-muted); font: inherit; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); text-align: left; cursor: pointer;
  transition: background var(--duration-fast, 150ms) var(--easing, ease), color var(--duration-fast, 150ms) var(--easing, ease);
}
.fl-ctl-vtab svg { flex: none; width: 1rem; height: 1rem; }
.fl-ctl-vtab > span:first-of-type { flex: 1; min-width: 0; }
.fl-ctl-vtab:hover { background: var(--color-surface-sunken); color: var(--color-text); }
.fl-ctl-vtab:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-ctl-vtab.is-on { color: var(--color-text); font-weight: 600; }
.fl-ctl-vtabs--plain .fl-ctl-vtab.is-on { box-shadow: inset 2px 0 0 var(--color-accent); margin-left: calc(var(--space-2) * -1); padding-left: calc(var(--space-3) + var(--space-2)); }
.fl-ctl-vtabs--filled .fl-ctl-vtab.is-on { background: color-mix(in srgb, var(--color-accent) 12%, transparent); color: var(--color-accent); }
.fl-ctl-vtab.is-off { opacity: 0.5; cursor: not-allowed; }
.fl-ctl-vtab-count { flex: none; border-radius: 999px; background: var(--color-surface-sunken); padding: 0 var(--space-2); font-size: var(--text-xs, 0.78rem); }
.fl-ctl-vtabs-panel { min-width: 0; border-radius: min(var(--surface-radius, var(--radius-lg)), 12px); background: var(--color-surface-sunken); padding: var(--space-4); }
.fl-ctl-vtabs-panel h4 { margin: 0 0 var(--space-2); }
.fl-ctl-vtabs-panel:focus-visible { outline: none; box-shadow: var(--focus-ring); }
/* Vertical tabs motion: one indicator (the side line, or the filled row) glides to the open section. It takes over from
   the open row's own mark only once measured (.is-sliding); the line stays straight and square. */
.fl-ctl-vtabs-rail { position: relative; }
.fl-ctl-vtabs__ind { position: absolute; left: 0; top: 0; z-index: 0; display: none; border-radius: 0; pointer-events: none; }
.fl-ctl-vtabs-rail.is-sliding .fl-ctl-vtabs__ind { display: block; }
.fl-ctl-vtabs-rail.is-sliding.is-ready .fl-ctl-vtabs__ind { transition: transform var(--duration-base) var(--ease-out, var(--easing)), width var(--duration-base) var(--ease-out, var(--easing)), height var(--duration-base) var(--ease-out, var(--easing)); }
.fl-ctl-vtabs-rail.is-sliding .fl-ctl-vtab { position: relative; z-index: 1; }
.fl-ctl-vtabs--plain .fl-ctl-vtabs__ind { box-shadow: inset 2px 0 0 var(--color-accent); }
.fl-ctl-vtabs--plain .fl-ctl-vtabs-rail.is-sliding .fl-ctl-vtab.is-on:not(:focus-visible) { box-shadow: none; }
.fl-ctl-vtabs--filled .fl-ctl-vtabs__ind { background: color-mix(in srgb, var(--color-accent) 12%, transparent); }
.fl-ctl-vtabs--filled .fl-ctl-vtabs-rail.is-sliding .fl-ctl-vtab.is-on { background: transparent; }
.fl-ctl-vtab { transition: background-color var(--duration-fast) var(--easing), color var(--duration-fast) var(--easing), padding var(--duration-fast) var(--easing); }
.fl-ctl-vtab:active:not(.is-off) { background: color-mix(in srgb, var(--color-text) 8%, transparent); }
.fl-ctl-vtab-count { transition: background-color var(--duration-fast) var(--easing), color var(--duration-fast) var(--easing); }
@container specimen (max-width: 760px) {
  .fl-ctl-vtabs--plain .fl-ctl-vtabs__ind { box-shadow: inset 0 -2px 0 var(--color-accent); }
}
@media (prefers-reduced-motion: reduce) {
  .fl-ctl-vtabs-rail.is-sliding.is-ready .fl-ctl-vtabs__ind, .fl-ctl-vtab-count { transition: none; }
}
:root[data-motion="off"] :is(.fl-ctl-vtab, .fl-ctl-vtab-count, .fl-ctl-vtabs__ind) { transition: none !important; animation: none !important; }

/* ── Top nav ────────────────────────────────────────────────────────────────── */
.fl-ctl-nav-list { display: grid; gap: var(--space-6); margin: 0 0 var(--space-5); padding: 0; list-style: none; }
.fl-ctl-nav-list > li { display: grid; gap: var(--space-1, 0.25rem); min-width: 0; }
.fl-ctl-nav {
  position: relative; display: flex; align-items: center; gap: var(--space-3); flex-wrap: wrap;
  margin-top: var(--space-2); border: var(--surface-border, 1px solid var(--color-border)); border-radius: min(var(--surface-radius, var(--radius-lg)), 12px);
  background: var(--surface-bg, var(--color-surface)); padding: var(--space-3) var(--space-4); box-shadow: var(--surface-shadow, none); backdrop-filter: var(--surface-blur, none); -webkit-backdrop-filter: var(--surface-blur, none);
}
