.fl-ctl-rows { display: grid; margin: var(--space-2) 0 0; padding: 0; border: var(--surface-border, 1px solid var(--color-border)); border-radius: min(var(--surface-radius, var(--radius-lg)), 12px); list-style: none; overflow: hidden; box-shadow: var(--surface-shadow, none); }
.fl-ctl-rows > li, .fl-ctl-rows > div { border-top: 1px solid var(--color-border); }
