a.fl-spec-row.is-on { background: color-mix(in srgb, var(--color-accent) 10%, transparent); }
a.fl-spec-row:focus-visible { outline: none; box-shadow: var(--focus-ring); }
button.fl-spec-row { width: 100%; border: 0; background: transparent; font: inherit; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); text-align: left; cursor: pointer; }
button.fl-spec-row:hover { background: var(--color-surface-sunken); }
button.fl-spec-row:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-ctl-row-chev { display: grid; flex: none; color: var(--color-text-muted); }
.fl-ctl-row-chev svg { width: 1rem; height: 1rem; }
.fl-ctl-row-chev:not(.is-open) svg { transform: rotate(-90deg); }
.fl-ctl-row-detail { padding: var(--space-3); border-top: 1px dashed var(--color-border); background: var(--color-surface-sunken); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-ctl-row-main { display: grid; flex: 1; gap: 2px; min-width: 0; }
.fl-ctl-row-main strong, .fl-ctl-row-main .fl-ctl-matrix-what { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
/* Unread: its own mark, in its own gutter. The gutter stays when the row is read, so nothing shifts under the
   pointer; only the dot goes. The name carries the weight, because a dot alone is a lot to ask of one colour. */
.fl-ctl-row-unread { flex: none; width: 0.5rem; height: 0.5rem; border-radius: 999px; background: transparent; }
.fl-spec-row.is-unread .fl-ctl-row-unread { background: var(--color-accent); }
.fl-ctl-rows--links .fl-spec-row .fl-ctl-row-main strong { font-weight: 500; }
