.fl-ctl-row-grip { transform: rotate(90deg); cursor: grab; }
.fl-ctl-row-up svg { transform: rotate(180deg); }
.fl-ctl-rows--order { counter-reset: none; }

/* ── Avatars ────────────────────────────────────────────────────────────────── */
.fl-ctl-avatar { position: relative; display: inline-grid; flex: none; place-items: center; border-radius: 999px; background: var(--color-surface-sunken); color: var(--color-text); font-weight: 700; line-height: 1; overflow: visible; }
