.fl-ctl-avatar.is-square { border-radius: var(--radius-md); }
.fl-ctl-avatar--20 { width: 20px; height: 20px; font-size: max(11px, calc(0.55rem - var(--fs-shrink, 0px))); }
.fl-ctl-avatar--24 { width: 24px; height: 24px; font-size: max(11px, calc(0.6rem - var(--fs-shrink, 0px))); }
.fl-ctl-avatar--32 { width: 32px; height: 32px; font-size: max(11px, calc(0.72rem - var(--fs-shrink, 0px))); }
.fl-ctl-avatar--40 { width: 40px; height: 40px; font-size: max(11px, calc(0.85rem - var(--fs-shrink, 0px))); }
.fl-ctl-avatar--48 { width: 48px; height: 48px; font-size: max(11px, calc(1rem - var(--fs-shrink, 0px))); }
.fl-ctl-avatar--64 { width: 64px; height: 64px; font-size: max(11px, calc(1.3rem - var(--fs-shrink, 0px))); }
.fl-ctl-avatar--44 { width: 44px; height: 44px; font-size: max(11px, calc(0.92rem - var(--fs-shrink, 0px))); }
.fl-ctl-avatar--72 { width: 72px; height: 72px; font-size: max(11px, calc(1.5rem - var(--fs-shrink, 0px))); }
.fl-ctl-avatar--96 { width: 96px; height: 96px; font-size: max(11px, calc(2rem - var(--fs-shrink, 0px))); }
.fl-ctl-avatar--120 { width: 120px; height: 120px; font-size: max(11px, calc(2.5rem - var(--fs-shrink, 0px))); }
.fl-ctl-avatar--96 .fl-ctl-avatar-dot, .fl-ctl-avatar--120 .fl-ctl-avatar-dot { right: 4%; bottom: 4%; width: 0.4em; height: 0.4em; border-width: 3px; }
.fl-ctl-avatar--a { background: var(--color-secondary-surface, color-mix(in srgb, var(--color-accent) 18%, transparent)); color: var(--color-text); }
.fl-ctl-avatar--b { background: color-mix(in srgb, var(--color-success, #157f3d) 18%, transparent); color: var(--color-success, #157f3d); }
.fl-ctl-avatar--c { background: color-mix(in srgb, var(--color-danger, #b42318) 15%, transparent); color: var(--color-danger, #b42318); }
.fl-ctl-avatar--d { background: color-mix(in srgb, var(--color-warning, #b45309) 18%, transparent); color: var(--color-warning, #b45309); }
.fl-ctl-avatar--e { background: var(--color-surface-sunken); color: var(--color-text-muted); }
.fl-ctl-avatar--rest { background: var(--color-surface-sunken); color: var(--color-text-muted); font-size: max(11px, calc(0.7rem - var(--fs-shrink, 0px))); }
.fl-ctl-avatar-dot { position: absolute; right: -1px; bottom: -1px; width: 0.55em; height: 0.55em; min-width: 8px; min-height: 8px; margin: 0; border: 2px solid var(--color-surface); border-radius: 999px; }
.fl-ctl-avatar-sizes li { align-items: center; }
.fl-ctl-avatar-row { display: flex; flex-wrap: wrap; gap: var(--space-5); margin-top: var(--space-3); }
.fl-ctl-avatar-pair { display: grid; justify-items: center; gap: var(--space-2); max-width: 9rem; text-align: center; }
.fl-ctl-avatar-people { display: grid; gap: var(--space-3); margin: var(--space-3) 0 0; padding: 0; list-style: none; }
.fl-ctl-avatar-people > li { display: flex; align-items: center; gap: var(--space-3); }
.fl-ctl-avatar-people > li > span:last-child { display: grid; gap: 2px; }
.fl-ctl-avatar-stack { display: inline-flex; margin-top: var(--space-3); }
.fl-ctl-avatar-stack > .fl-ctl-avatar { border: 2px solid var(--color-surface); margin-left: -0.6rem; }
.fl-ctl-avatar-stack > .fl-ctl-avatar:first-child { margin-left: 0; }
.fl-ctl-avatar-more { display: inline-flex; margin-left: -0.6rem; padding: 0; border: 0; border-radius: 999px; background: none; cursor: pointer; }
.fl-ctl-avatar-more .fl-ctl-avatar { border: 2px solid var(--color-surface); }
.fl-ctl-avatar-more:focus-visible { outline: none; box-shadow: var(--focus-ring); }

/* ── Media frames ───────────────────────────────────────────────────────────── */
.fl-ctl-media-row { display: flex; flex-wrap: wrap; gap: var(--space-4); margin: var(--space-3) 0 var(--space-4); padding: 0; list-style: none; }
.fl-ctl-media-row > li { display: grid; gap: 2px; width: 9rem; }
.fl-ctl-media { position: relative; display: block; width: 100%; border-radius: min(var(--surface-radius-sm, var(--radius-md)), 12px); background: var(--color-surface-sunken); overflow: hidden; }
