.fl-ctl-media--4-3 { aspect-ratio: 4 / 3; }
.fl-ctl-media--16-9 { aspect-ratio: 16 / 9; }
.fl-ctl-media--3-4 { aspect-ratio: 3 / 4; }
.fl-ctl-media-art { position: absolute; inset: 0; }
.fl-ctl-media-art--a { background: linear-gradient(135deg, color-mix(in srgb, var(--color-secondary, var(--color-accent)) 70%, #000), color-mix(in srgb, var(--color-secondary, var(--color-accent)) 25%, var(--color-surface))); }
.fl-ctl-media-art--b { background: linear-gradient(160deg, color-mix(in srgb, var(--color-warning, #b45309) 70%, #000), color-mix(in srgb, var(--color-danger, #b42318) 40%, var(--color-surface))); }
.fl-ctl-media-art--c { background: linear-gradient(200deg, color-mix(in srgb, var(--color-success, #157f3d) 65%, #000), color-mix(in srgb, var(--color-success, #157f3d) 20%, var(--color-surface))); }
.fl-ctl-media-art--d { background: linear-gradient(120deg, color-mix(in srgb, var(--color-text) 60%, var(--color-secondary, var(--color-accent))), color-mix(in srgb, var(--color-secondary, var(--color-accent)) 30%, var(--color-surface))); }
.fl-ctl-media-art--e { background: linear-gradient(135deg, var(--color-text-muted), var(--color-surface-sunken)); }
.fl-ctl-media-art.is-cover { inset: 0; }
.fl-ctl-media-art.is-contain { inset: 0 34%; }
.fl-ctl-media-pair { display: grid; gap: var(--space-4); grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr)); margin-top: var(--space-3); }
.fl-ctl-media-pair > span { display: grid; gap: 2px; min-width: 0; }
.fl-ctl-media-grid { display: grid; gap: var(--space-4); grid-template-columns: repeat(auto-fill, minmax(10rem, 1fr)); margin: var(--space-3) 0 0; padding: 0; list-style: none; }
.fl-ctl-media-fig { display: grid; gap: var(--space-2); margin: 0; }
.fl-ctl-media-fig figcaption { font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }
.fl-ctl-media-skel { position: absolute; inset: 0; height: auto; border-radius: 0; }
.fl-ctl-media-gone { position: absolute; inset: 0; display: grid; place-content: center; justify-items: center; gap: var(--space-2); color: var(--color-text-muted); text-align: center; }
.fl-ctl-media-gone svg { width: 1.5rem; height: 1.5rem; }

/* ── Dividers ───────────────────────────────────────────────────────────────── */
.fl-ctl-div-list { display: grid; gap: var(--space-4); margin: var(--space-3) 0 0; padding: 0; list-style: none; }
.fl-ctl-div-list > li { display: grid; gap: 2px; }
.fl-ctl-div-list.has-rules { gap: 0; }
.fl-ctl-div-list.has-rules > li { padding: var(--space-3) 0; border-top: 1px solid var(--color-border); }
.fl-ctl-div-list.has-rules > li:first-child { border-top: 0; padding-top: 0; }
.fl-ctl-rule { height: 0; margin: 0; border: 0; border-top: 1px solid var(--color-border); }
.fl-ctl-rule--hair { border-top-color: color-mix(in srgb, var(--color-border) 55%, transparent); }
.fl-ctl-rule--heavy { border-top-width: 2px; border-top-color: var(--color-border-strong, var(--color-border)); }
.fl-ctl-rule--dash { border-top-style: dashed; }
.fl-ctl-div-weights { display: grid; gap: var(--space-2); margin-top: var(--space-3); }
.fl-ctl-div-bar { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-1, 0.25rem); margin-top: var(--space-3); border: var(--surface-border, 1px solid var(--color-border)); border-radius: min(var(--surface-radius-sm, var(--radius-md)), 12px); padding: var(--space-2); width: max-content; max-width: 100%; }
.fl-ctl-vrule { width: 1px; align-self: stretch; margin: 0 var(--space-2); background: var(--color-border); }
.fl-ctl-div-labelled { display: grid; gap: var(--space-3); max-width: 24rem; margin-top: var(--space-3); }
.fl-ctl-rule-label { display: flex; align-items: center; gap: var(--space-3); color: var(--color-text-muted); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); }
.fl-ctl-rule-label::before, .fl-ctl-rule-label::after { content: ""; flex: 1; height: 1px; background: var(--color-border); }
.fl-ctl-rule-label--start { margin-top: var(--space-4); }
.fl-ctl-rule-label--start::before { flex: 0 0 var(--space-4); }

/* ── Chat ───────────────────────────────────────────────────────────────────── */
.fl-ctl-chat { display: grid; max-width: 32rem; border: var(--surface-border, 1px solid var(--color-border)); border-radius: min(var(--radius-lg), 12px); background: var(--surface-bg, var(--color-surface)); overflow: hidden; box-shadow: var(--surface-shadow, none); backdrop-filter: var(--surface-blur, none); -webkit-backdrop-filter: var(--surface-blur, none); }
.fl-ctl-chat-head { display: flex; align-items: center; gap: var(--space-3); border-bottom: 1px solid var(--color-border); padding: var(--space-3) var(--space-4); }
.fl-ctl-chat-head > span:last-child { display: grid; gap: 2px; }
.fl-ctl-chat-head .fl-ctl-dot { display: inline-block; margin: 0 var(--space-1, 0.25rem) 0 0; }
.fl-ctl-chat-log { display: grid; gap: var(--space-2); max-height: 22rem; overflow-y: auto; margin: 0; padding: var(--space-4); list-style: none; }
.fl-ctl-msg { display: flex; align-items: flex-end; gap: var(--space-2); }
.fl-ctl-msg.is-first { margin-top: var(--space-3); }
.fl-ctl-msg:first-child { margin-top: 0; }
.fl-ctl-msg--me { flex-direction: row-reverse; }
.fl-ctl-msg-face { width: 24px; flex: none; }
.fl-ctl-msg-col { display: grid; gap: 2px; max-width: 75%; }
.fl-ctl-msg--me .fl-ctl-msg-col { justify-items: end; }
.fl-ctl-msg-who { color: var(--color-text-muted); font-size: var(--text-xs, 0.78rem); }
.fl-ctl-bubble { display: inline-block; border-radius: min(var(--radius-lg), 12px); background: var(--color-surface-sunken); padding: var(--space-2) var(--space-3); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); line-height: 1.5; }
.fl-ctl-msg--me .fl-ctl-bubble { background: var(--color-secondary, var(--color-accent)); color: var(--color-on-secondary, var(--color-on-accent, #fff)); }
.fl-ctl-msg.is-failed .fl-ctl-bubble { background: color-mix(in srgb, var(--color-danger, #b42318) 14%, transparent); color: var(--color-text); border: 1px solid var(--color-danger, #b42318); }
.fl-ctl-msg-state { display: flex; align-items: center; gap: var(--space-2); color: var(--color-text-muted); font-size: var(--text-xs, 0.78rem); }
.fl-ctl-msg.is-failed .fl-ctl-msg-state { color: var(--color-danger, #b42318); }
.fl-ctl-msg-retry { display: inline-flex; align-items: center; gap: 2px; border: 0; background: none; padding: 0; color: inherit; font: inherit; text-decoration: underline; cursor: pointer; }
.fl-ctl-msg-retry svg { width: 0.75rem; height: 0.75rem; }
.fl-ctl-bubble--typing { display: inline-flex; gap: 3px; align-items: center; }
.fl-ctl-bubble--typing > span { width: 6px; height: 6px; border-radius: 999px; background: var(--color-text-muted); animation: fl-ctl-blink 1.2s var(--easing, ease) infinite; }
.fl-ctl-bubble--typing > span:nth-child(2) { animation-delay: 0.15s; }
.fl-ctl-bubble--typing > span:nth-child(3) { animation-delay: 0.3s; }
/* Chat motion: a new message (or the typing bubble) rises in from its own side; a delivery line that changes fades
   in; the typing dots hop; Try again presses in. Messages already there on load don't animate. */
.fl-ctl-msg.is-new { animation: fl-ctl-msg-in var(--duration-base, 200ms) var(--ease-out, var(--easing, ease)) both; transform-origin: left bottom; }
.fl-ctl-msg--me.is-new { transform-origin: right bottom; }
.fl-ctl-msg-state.is-changed { animation: fl-ctl-msg-fade var(--duration-base, 200ms) var(--ease-out, var(--easing, ease)); }
.fl-ctl-bubble--typing > span[aria-hidden] { animation-name: fl-ctl-typing; }
.fl-ctl-msg-retry { border-radius: var(--radius-sm); transition: color var(--duration-fast, 120ms) var(--easing, ease), translate var(--duration-fast, 120ms) var(--easing, ease); }
.fl-ctl-msg-retry:hover { color: var(--color-text); }
.fl-ctl-msg-retry:hover svg { rotate: -90deg; }
.fl-ctl-msg-retry svg { transition: rotate var(--duration-base, 200ms) var(--ease-spring, var(--easing, ease)); }
.fl-ctl-msg-retry:active { translate: 0 1px; }
.fl-ctl-msg-retry:focus-visible { outline: none; box-shadow: var(--focus-ring); }
@keyframes fl-ctl-msg-in { from { opacity: 0; transform: translateY(var(--enter-distance, 8px)) scale(0.96); } }
@keyframes fl-ctl-msg-fade { from { opacity: 0; } }
@keyframes fl-ctl-typing { 0%, 60%, 100% { opacity: 0.35; translate: 0 0; } 30% { opacity: 1; translate: 0 -3px; } }
@media (prefers-reduced-motion: reduce) {
  .fl-ctl-msg.is-new { animation: fl-ctl-msg-fade 120ms linear both; }
  .fl-ctl-bubble--typing > span[aria-hidden] { animation: none; opacity: 0.6; }
  .fl-ctl-msg-retry, .fl-ctl-msg-retry svg { transition: none; }
  .fl-ctl-msg-retry:hover svg { rotate: none; }
  .fl-ctl-msg-retry:active { translate: none; }
}
:root[data-motion="off"] :is(.fl-ctl-msg, .fl-ctl-msg *) { animation: none !important; transition: none !important; }
.fl-ctl-msg--ai { display: block; }
.fl-ctl-msg--ai .fl-ctl-msg-col { max-width: none; justify-items: stretch; }
.fl-ctl-msg--ai .fl-ctl-bubble { display: block; background: none; padding: 0; border-radius: 0; color: var(--color-text); line-height: 1.65; }
.fl-ctl-msg--ai .fl-ctl-bubble > :first-child { margin-top: 0; }
.fl-ctl-msg--ai .fl-ctl-bubble > :last-child { margin-bottom: 0; }
.fl-ctl-msg--ai .fl-ctl-bubble p, .fl-ctl-msg--ai .fl-ctl-bubble ul, .fl-ctl-msg--ai .fl-ctl-bubble ol { margin: 0 0 var(--space-3); }
.fl-ctl-msg--ai .fl-ctl-bubble ul, .fl-ctl-msg--ai .fl-ctl-bubble ol { padding-left: 1.25rem; }
.fl-ctl-msg--ai .fl-ctl-bubble pre { margin: 0 0 var(--space-3); padding: var(--space-3); overflow-x: auto; border: 1px solid var(--color-border); border-radius: var(--radius-md); background: var(--color-surface-sunken); font-size: var(--text-xs, 0.78rem); line-height: 1.5; }
.fl-ctl-msg--ai .fl-ctl-bubble code { font-family: var(--font-mono, ui-monospace, monospace); font-size: 0.92em; }
.fl-ctl-msg--ai .fl-ctl-bubble :not(pre) > code { padding: 0.1em 0.35em; border-radius: var(--radius-sm); background: var(--color-surface-sunken); }
.fl-ctl-msg-actions { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-1, 0.25rem); margin-top: var(--space-1, 0.25rem); }
.fl-ctl-msg--ai .fl-ctl-ai-head { margin-top: var(--space-2); }
@keyframes fl-ctl-blink { 0%, 60%, 100% { opacity: 0.3; } 30% { opacity: 1; } }
.fl-ctl-chat-send { display: flex; gap: var(--space-2); border-top: 1px solid var(--color-border); padding: var(--space-3); }

/* ── AI indicators ──────────────────────────────────────────────────────────── */
.fl-ctl-ai-card, .fl-ctl-ai-stream {
  display: grid; gap: var(--space-3); margin-top: var(--space-3); border: 1px solid var(--color-secondary-border, color-mix(in srgb, var(--color-accent) 35%, var(--color-border)));
  border-radius: min(var(--radius-lg), 12px); background: linear-gradient(180deg, color-mix(in srgb, var(--color-secondary, var(--color-accent)) 5%, var(--color-surface)), var(--color-surface));
  padding: var(--space-4);
}
.fl-ctl-ai-card p, .fl-ctl-ai-stream p { margin: 0; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); line-height: 1.6; }
.fl-ctl-ai-head { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-3); }
.fl-ctl-ai-badge { display: inline-flex; align-items: center; gap: var(--space-1, 0.25rem); border-radius: 999px; background: var(--color-secondary-surface, color-mix(in srgb, var(--color-accent) 16%, transparent)); color: var(--color-text); padding: 2px var(--space-2); font-size: var(--text-xs, 0.78rem); font-weight: 700; }
.fl-ctl-ai-badge svg { width: 0.875rem; height: 0.875rem; }
.fl-ctl-ai-foot { display: flex; flex-wrap: wrap; align-items: center; gap: var(--space-2); }
.fl-ctl-ai-pulse { width: 0.5rem; height: 0.5rem; border-radius: 999px; background: var(--color-accent); animation: fl-ctl-pulse 1.2s var(--easing, ease) infinite; }
@keyframes fl-ctl-pulse { 50% { opacity: 0.25; transform: scale(0.7); } }
.fl-ctl-ai-caret { display: inline-block; width: 2px; height: 1em; margin-left: 2px; background: var(--color-accent); vertical-align: text-bottom; animation: fl-ctl-blink 1s steps(2) infinite; }
.fl-ctl-ai-field { position: relative; display: block; }
.fl-ctl-ai-ghost { position: absolute; inset: 0; display: flex; align-items: center; padding-inline: var(--space-3); color: var(--color-text-muted); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); font-style: italic; pointer-events: none; overflow: hidden; white-space: nowrap; }
.fl-ctl-ai-sure { display: grid; gap: var(--space-4); margin: var(--space-3) 0 0; padding: 0; list-style: none; }
