  min-width: var(--control-sm); height: var(--control-sm); padding-inline: var(--space-2); border-radius: var(--control-radius, var(--radius-sm));
  border: 1px solid var(--color-border); background: var(--color-surface); color: var(--color-text);
  font: var(--weight-semibold) max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))) / 1 var(--font-sans); font-variant-numeric: tabular-nums; cursor: pointer;
