.fl-plan-feat-head { color: var(--color-text-muted); font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); font-weight: var(--weight-semibold); letter-spacing: var(--tracking-wide); text-transform: uppercase; vertical-align: bottom !important; }
