.fl-plan-table thead th:first-child { width: 32%; }
.fl-plan-col { min-width: 10rem; }
.fl-plan-table thead .fl-plan-col { padding-block: var(--space-4); }
.fl-plan-col.is-pick { background: var(--color-secondary-surface, color-mix(in srgb, var(--color-accent) 7%, var(--color-surface))); }
.fl-plan-table thead .fl-plan-col > * + * { margin-top: var(--space-2); }
.fl-plan-name { display: flex; flex-wrap: wrap; gap: var(--space-2); align-items: center; font: var(--weight-semibold) max(11px, calc(var(--text-md) - var(--fs-shrink, 0px))) / var(--leading-snug) var(--font-display); }
.fl-plan-price { display: flex; align-items: baseline; gap: var(--space-1); }
.fl-plan-price strong { font: var(--weight-bold) max(11px, calc(var(--text-2xl) - var(--fs-shrink, 0px))) / 1 var(--font-display); font-variant-numeric: tabular-nums; }
.fl-plan-price span, .fl-plan-note { color: var(--color-text-muted); font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); font-weight: var(--weight-regular); }
.fl-plan-note { display: block; }
/* A group heading names the features under it; it doesn't open or close. */
.fl-plan-group th { padding: var(--space-2) var(--space-4); background: var(--color-surface-sunken); color: var(--color-text); font-weight: var(--weight-semibold); font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); letter-spacing: var(--tracking-wide); text-transform: uppercase; }
/* A feature row opens: its name is the button, and its details appear under the name. */
