.fl-plan-feat { font-weight: var(--weight-medium); }
.fl-plan-feat-btn {
  display: flex; align-items: flex-start; gap: var(--space-2); width: 100%; margin: calc(var(--space-1) * -1) 0; padding: var(--space-1) 0; border: 0; border-radius: var(--radius-sm);
  background: none; color: inherit; font: inherit; text-align: left; cursor: pointer;
}
.fl-plan-feat-btn:hover { color: var(--color-accent); }
.fl-plan-feat-btn:focus-visible { outline: none; box-shadow: var(--focus-ring); }
.fl-plan-feat-text { display: block; padding-left: calc(1rem + var(--space-2)); }
.fl-plan-caret { display: inline-grid; place-items: center; flex: none; width: 1rem; height: 1.25rem; color: var(--color-text-muted); transition: transform var(--duration-fast) var(--easing); }
