.fl-plan-detail { display: block; max-width: 100%; margin-top: var(--space-2); padding-left: calc(1rem + var(--space-2)); color: var(--color-text-muted); font-size: max(11px, calc(var(--text-xs) - var(--fs-shrink, 0px))); font-weight: var(--weight-regular); line-height: var(--leading-normal); }
.fl-plan-detail[hidden] { display: none; }
.fl-plan-yes { display: inline-grid; place-items: center; color: var(--color-success); }
.fl-plan-yes svg { width: 1.1rem; height: 1.1rem; }
.fl-plan-no { color: var(--color-text-muted); }
.fl-plan-table tbody:last-child tr:last-child > * { border-bottom: 0; }
@media (prefers-reduced-motion: reduce) { .fl-plan-caret { transition: none; } }


/**
 * Team members table (p.members-table): a header with a seat meter and Invite, search and role filter, then a table of
 * people with an inline role dropdown, a status pill and quiet row actions; each row becomes a card on a narrow screen.
 * Prefixed fl-tm-; only the library's tokens. Adapted from HyperUI (MIT License, Copyright (c) Mark Mead).
 */
.fl-tm { container-type: inline-size; display: grid; gap: var(--space-4); min-width: 0; }
.fl-tm-head { display: flex; flex-wrap: wrap; align-items: flex-end; justify-content: space-between; gap: var(--space-4); }
.fl-tm-heading { display: grid; gap: var(--space-1); min-width: 0; }
