.fl-tm-note { display: flex; align-items: center; gap: var(--space-2); margin: 0; font-size: max(11px, calc(var(--text-sm) - var(--fs-shrink, 0px))); color: var(--color-text-muted); }
.fl-tm-note svg { width: 1rem; height: 1rem; flex: none; color: var(--color-warning); }

.fl-tm-tools { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.fl-tm-search { position: relative; flex: 1 1 14rem; max-width: 24rem; }
.fl-tm-search > svg { position: absolute; left: var(--space-3); top: 50%; translate: 0 -50%; width: 1rem; height: 1rem; color: var(--color-text-muted); pointer-events: none; }
